INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100047, 100205, 'ROADMAP_QUIZ', 'What is the function of ''There is'' and ''There are'' in a sentence?', 'Chức năng của ''There is'' và ''There are'' là để chỉ sự tồn tại của một thứ gì đó trong một không gian hoặc tình huống cụ thể.', 'A1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100047, 'A', 'To indicate possession', false);
