INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100047, 'D', 'To indicate time', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100048, 100205, 'ROADMAP_QUIZ', 'Which sentence is grammatically incorrect?', 'Câu ''There is dogs in the park'' là câu không đúng ngữ pháp vì sử dụng ''There is'' với danh từ số nhiều ''dogs''.', 'A1') ON CONFLICT (id) DO NOTHING;
