INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100048, 'D', 'There is dogs in the park', true);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100049, 100205, 'ROADMAP_QUIZ', 'What is the correct way to express that there are no things?', 'Cách đúng để biểu thị rằng không có thứ gì là sử dụng ''There are no things'', vì ''no'' đi với ''are'' khi nói về số nhiều.', 'A1') ON CONFLICT (id) DO NOTHING;
