INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (100207, '# Cấu trúc/Công thức 
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100061, 100207, 'ROADMAP_QUIZ', 'Where are adjectives usually placed in a sentence?', 'Adjectives thường được đặt trước noun trong câu để mô tả tính chất, đặc điểm của sự vật, sự việc.', 'A1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100061, 'A', 'After the noun', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100061, 'B', 'Before the noun', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100061, 'C', 'At the end of the sentence', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100061, 'D', 'At the beginning of the sentence', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100062, 100207, 'ROADMAP_QUIZ', 'What is the function of adjectives in a sentence?', 'Adjectives dùng để mô tả tính chất, đặc điểm của sự vật, sự việc, giúp câu văn thêm丰富 và sinh động.', 'A1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100062, 'A', 'To show action', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100062, 'B', 'To describe a person, place, or thing', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100062, 'C', 'To indicate time', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100062, 'D', 'To show location', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100063, 100207, 'ROADMAP_QUIZ', 'Which of the following is an example of a correctly placed adjective?', 'Adjectives thường được đặt trước noun, vì vậy ''The big house'' là ví dụ đúng.', 'A1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100063, 'A', 'House big the', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100063, 'B', 'The big house', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100063, 'C', 'Big the house', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100063, 'D', 'House the big', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100064, 100207, 'ROADMAP_QUIZ', 'What is a common mistake when using adjectives?', 'Một lỗi thường gặp khi sử dụng adjectives là đặt chúng sau noun, thay vì trước noun.', 'A1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100064, 'A', 'Placing them before the noun', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100064, 'B', 'Using them to describe verbs', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100064, 'C', 'Placing them after the noun', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100064, 'D', 'Not using them at all', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100065, 100207, 'ROADMAP_QUIZ', 'How can you improve your use of adjectives?', 'Học các nhóm từ vựng theo chủ đề, bao gồm cả adjectives, và luyện tập đặt chúng đúng vị trí sẽ giúp cải thiện việc sử dụng adjectives.', 'A1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100065, 'A', 'By learning new nouns', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100065, 'B', 'By learning new verbs', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100065, 'C', 'By learning new adjectives and practicing their placement', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100065, 'D', 'By not using adjectives at all', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100066, 100207, 'ROADMAP_QUIZ', 'What is the correct order of words in the sentence ''The house is big'' in terms of adjective placement?', 'Trong câu ''The big house'', từ ''big'' là adjective, ''The'' là article, và ''house'' là noun. Vậy công thức đúng là Article, Adjective, Noun.', 'A1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100066, 'A', 'Adjective, Article, Noun', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100066, 'B', 'Article, Adjective, Noun', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100066, 'C', 'Noun, Article, Adjective', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100066, 'D', 'Article, Noun, Adjective', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100067, 100207, 'ROADMAP_QUIZ', 'Which sentence is grammatically correct?', 'Câu ''The big house is mine'' là câu đúng về mặt ngữ pháp, với adjective ''big'' được đặt trước noun ''house''.', 'A1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100067, 'A', 'The house big is mine', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100067, 'B', 'The big house is mine', true);
