INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100067, 'D', 'House the big is mine', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100068, 100207, 'ROADMAP_QUIZ', 'What is the purpose of learning adjectives in groups by theme?', 'Học adjectives theo nhóm từ vựng theo chủ đề giúp cải thiện vốn từ vựng và hiểu rõ cách sử dụng adjectives trong ngữ cảnh cụ thể.', 'A1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100068, 'A', 'To learn new nouns', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100068, 'B', 'To learn new verbs', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100068, 'C', 'To improve vocabulary and understand how adjectives are used in context', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100068, 'D', 'To ignore adjectives', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100069, 100207, 'ROADMAP_QUIZ', 'Which of the following adjectives is used to describe a person?', 'Tất cả các adjectives ''Happy'', ''Big'', ''Old'' đều có thể được sử dụng để mô tả một người.', 'A1') ON CONFLICT (id) DO NOTHING;
