INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100070, 100207, 'ROADMAP_QUIZ', 'Why is it important to learn the correct placement of adjectives?', 'Học cách đặt adjectives đúng vị trí giúp bạn giao tiếp rõ ràng và hiệu quả hơn, vì nó làm cho câu văn của bạn có ý nghĩa và dễ hiểu hơn.', 'A1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100070, 'A', 'So that you can speak faster', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100070, 'B', 'So that you can write more', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100070, 'C', 'So that you can communicate more clearly and effectively', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100070, 'D', 'So that you can ignore grammar rules', false);
