INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100516, 101810, 'ROADMAP_QUIZ', 'Cấu trúc của từ nối và từ liên kết phức tạp bao gồm?', 'Cấu trúc của từ nối và từ liên kết phức tạp thường bao gồm một hoặc nhiều từ nối và từ liên kết được sử dụng để kết nối các ý tưởng, câu hoặc đoạn văn.', 'C1') ON CONFLICT (id) DO NOTHING;
