INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (100301, 'reading-a1-my-daily-routine', 1003, 'My Daily Routine', 1, 'READING', 'A1', 1.0, 'My Daily Routine') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (100301, 'I wake up at 6:00 every morning. I brush my teeth and wash my face. Then, I have breakfast. My mom makes me a sandwich and a glass of milk. I eat quickly because I don''t want to be late for school. I take the bus to school. The bus ride takes about 20 minutes. I sit with my friends and we talk about our weekend. When I arrive at school, I go to my classroom. My teacher gives us a lot of homework. I try to do my homework during recess. After school, I go home and do my homework. Then, I play with my friends until dinner time. My mom makes me a delicious dinner. I eat and watch TV until bedtime.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100527, 100301, 'ROADMAP_QUIZ', 'What time do I wake up?', 'Tôi thức dậy lúc 6:00 mỗi sáng.', 'A1') ON CONFLICT (id) DO NOTHING;
