INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (100303, 'reading-a1-a-day-at-the-zoo', 1003, 'A Day at the Zoo', 3, 'READING', 'A1', 1.0, 'A Day at the Zoo') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (100303, 'It''s a sunny day. Emma and her family are going to the zoo. They take the bus to get there. The bus ride is fun. Emma sees a lot of people on the bus. She also sees a big advertisement for the zoo. It says, ''Come and see the animals!'' Emma is excited. When they arrive at the zoo, Emma sees a big lion. She says, ''Wow, look at that!'' Her mom says, ''Yes, it''s a big lion.'' Emma also sees a monkey. She says, ''I want to see the monkey up close.'' Her dad says, ''Let''s go and see the monkey.'' They go to the monkey''s house. Emma sees the monkey eating bananas. She says, ''The monkey likes bananas!'' Her mom says, ''Yes, monkeys like bananas.'' Emma has a great time at the zoo. She sees a lot of animals and has fun with her family.', 'Vietnamese Translation:
