INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (100305, 'reading-a1-a-simple-recipe-for-pancakes', 1003, 'A Simple Recipe for Pancakes', 5, 'READING', 'A1', 1.0, 'A Simple Recipe for Pancakes') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (100305, 'Here''s a simple recipe for pancakes. You will need 1 cup of milk, 1 egg, and 1 cup of flour. First, mix the milk and egg together in a bowl. Then, add the flour and mix until it''s smooth. Heat a pan on the stove and put some oil in it. When the oil is hot, pour some of the mixture into the pan. Cook for 2 minutes and then flip the pancake over. Cook for another minute and then it''s ready.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100547, 100305, 'ROADMAP_QUIZ', 'What do we need to make pancakes?', 'Chúng ta cần 1 cốc sữa và 1 cốc bột mì để làm bánh kếp.', 'A1') ON CONFLICT (id) DO NOTHING;
