INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (100309, 'reading-a1-an-invitation-to-a-birthday-party', 1003, 'An Invitation to a Birthday Party', 9, 'READING', 'A1', 1.0, 'An Invitation to a Birthday Party') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (100309, 'It''s Emma''s birthday. She is 8 years old. Her friend, Olivia, wants to invite her to a party. Olivia writes a letter to Emma. ''Dear Emma, I''m having a birthday party on Saturday. You can come and play games with me. We will eat cake and ice cream. Please come at 2 o''clock. I''ll give you a present. Love, Olivia.'' Emma is very happy. She writes a letter back to Olivia. ''Dear Olivia, thank you for inviting me to your party. I''ll come at 2 o''clock. I love you. Love, Emma.''', 'Vietnamese Translation:
