INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (100706, 'reading-a2-job-description-for-an-administrative-assistant', 1007, 'Job Description for an Administrative Assistant', 6, 'READING', 'A2', 1.0, 'Job Description for an Administrative Assistant') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (100706, 'An administrative assistant is responsible for performing a variety of tasks to support the smooth operation of an office. These tasks may include answering phones, responding to emails, and greeting visitors. The assistant may also be responsible for managing schedules, making travel arrangements, and preparing reports. In addition, the assistant may be required to perform basic bookkeeping tasks, such as processing invoices and paying bills. The administrative assistant may work in a variety of settings, including private companies, government agencies, and non-profit organizations.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100653, 100706, 'ROADMAP_QUIZ', 'What is the main responsibility of an administrative assistant?', 'Trợ lý hành chính có trách nhiệm thực hiện một loạt các nhiệm vụ để hỗ trợ hoạt động trơn tru của một văn phòng.', 'A2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100653, 'A', 'To manage schedules and make travel arrangements', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100653, 'B', 'To answer phones and respond to emails', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100653, 'C', 'To perform basic bookkeeping tasks', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100653, 'D', 'All of the above', true);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100654, 100706, 'ROADMAP_QUIZ', 'Where may an administrative assistant work?', 'Trợ lý hành chính có thể làm việc trong nhiều môi trường khác nhau.', 'A2') ON CONFLICT (id) DO NOTHING;
