INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (100709, 'reading-a2-safety-instructions-for-fire-drills', 1007, 'Safety Instructions for Fire Drills', 9, 'READING', 'A2', 1.0, 'Safety Instructions for Fire Drills') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (100709, 'In case of a fire, please stay calm and follow these steps. First, go to the nearest exit. Do not use the elevator. If the door is hot, do not open it. Find another way out. Once you are outside, go to the assembly point. Do not run. Walk quickly and quietly. If you see someone who is hurt, help them. Call the fire department. Do not try to put out the fire yourself. Wait for the firefighters to arrive.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100668, 100709, 'ROADMAP_QUIZ', 'What should you do if the door is hot?', 'Nếu cửa là nóng, bạn nên tìm một lối thoát khác.', 'A2') ON CONFLICT (id) DO NOTHING;
