INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (100720, 'reading-a2-company-holiday-notice', 1007, 'Company Holiday Notice', 20, 'READING', 'A2', 1.0, 'Company Holiday Notice') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (100720, 'Dear employees, we are pleased to announce that our company will be closed for the summer holiday from August 1st to August 31st. During this time, all employees will receive a paid vacation. We will reopen on September 1st. Please note that the office will be closed on July 4th for Independence Day. If you have any urgent matters, please contact your supervisor. Thank you for your understanding.', 'Vietnamese Translation:
