INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101101, 'reading-b1-client-feedback-report-summary', 1011, 'Client Feedback Report Summary', 1, 'READING', 'B1', 1.0, 'Client Feedback Report Summary') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101101, 'The client feedback report for the marketing campaign is now available. According to the report, the campaign was successful in reaching 80% of the target audience. However, there were some issues with the website''s user interface, which caused 20% of the users to drop out. The report also suggests that the campaign''s social media strategy was effective in engaging the audience, but the email marketing strategy was less successful. Overall, the campaign''s results were mixed, and further analysis is needed to identify areas for improvement.', 'Vietnamese Translation:
