INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101103, 'reading-b1-the-benefits-of-remote-work', 1011, 'The Benefits of Remote Work', 3, 'READING', 'B1', 1.0, 'The Benefits of Remote Work') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101103, 'The shift to remote work has been a game-changer for many employees. Without the daily commute, they have more time to focus on their work and be more productive. According to a recent study, remote workers are 23% more productive than their office-based counterparts. This is because they can create their own schedule and work in a quiet environment that suits their needs. Additionally, remote workers have more flexibility to take breaks and recharge, which can lead to improved mental health and well-being. However, some employees may struggle with the lack of social interaction and face-to-face communication. To combat this, many companies are implementing virtual team-building activities and regular video check-ins. By embracing remote work, businesses can attract top talent and improve employee satisfaction, leading to increased productivity and success.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100738, 101103, 'ROADMAP_QUIZ', 'Theo nghiên cứu gần đây, nhân viên làm việc từ xa hiệu quả hơn nhân viên làm việc tại văn phòng bao nhiêu phần trăm?', 'Theo nghiên cứu gần đây, nhân viên làm việc từ xa hiệu quả hơn nhân viên làm việc tại văn phòng 23%.', 'B1') ON CONFLICT (id) DO NOTHING;
