INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101104, 'reading-b1-product-recall-notice', 1011, 'Product Recall Notice', 4, 'READING', 'B1', 1.0, 'Product Recall Notice') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101104, 'Dear valued customers, we are writing to inform you that our company has issued a product recall notice for certain batches of our popular ''QuickBite'' energy bars. The affected batches were produced between March 10th and April 15th and have been found to contain high levels of lead, which is a potential health risk. We urge all customers who have purchased these energy bars to stop consuming them immediately and return them to the store where they were purchased for a full refund. We apologize for any inconvenience this may cause and appreciate your cooperation in this matter. If you have any questions or concerns, please do not hesitate to contact us at 1-800-QUICK-BITE.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100743, 101104, 'ROADMAP_QUIZ', 'Tại sao công ty đã phát hành thông báo thu hồi sản phẩm?', 'Công ty đã phát hành thông báo thu hồi sản phẩm vì sản phẩm chứa chì, gây rủi ro sức khỏe cho khách hàng.', 'B1') ON CONFLICT (id) DO NOTHING;
