INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101107, 'reading-b1-company-policy-on-using-personal-laptops', 1011, 'Company Policy on Using Personal Laptops', 7, 'READING', 'B1', 1.0, 'Company Policy on Using Personal Laptops') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101107, 'As of today, our company will be implementing a new policy regarding the use of personal laptops in the workplace. According to this policy, all employees are allowed to bring their personal laptops to work, but they must be used for work-related purposes only. This means that personal emails, social media, and online shopping are strictly prohibited during work hours. Employees who fail to comply with this policy may face disciplinary action, up to and including termination of employment. We understand that this may cause some inconvenience, but we believe that this policy will help to increase productivity and reduce distractions in the workplace. If you have any questions or concerns, please do not hesitate to reach out to your supervisor or HR representative.', 'Vietnamese Translation:
