INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101110, 'reading-b1-operating-a-3d-printer', 1011, 'Operating a 3D Printer', 10, 'READING', 'B1', 1.0, 'Operating a 3D Printer') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101110, 'Before you start using the 3D printer, make sure you have read and understood the safety guidelines. The printer is equipped with a heated bed, which can reach temperatures of up to 120°C. Always wear protective gloves and safety glasses when handling the printer.
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100770, 101110, 'ROADMAP_QUIZ', 'What should you do before starting to use the 3D printer?', 'Hãy đọc và hiểu các hướng dẫn an toàn trước khi bắt đầu sử dụng máy in 3D.', 'B1') ON CONFLICT (id) DO NOTHING;
