INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100774, 101110, 'ROADMAP_QUIZ', 'What should you do if you encounter any issues during the printing process?', 'Nếu bạn gặp bất kỳ vấn đề nào trong quá trình in, hãy tham khảo hướng dẫn người dùng hoặc liên hệ với đội hỗ trợ của nhà sản xuất.', 'B1') ON CONFLICT (id) DO NOTHING;
