INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101111, 'reading-b1-the-basics-of-digital-marketing', 1011, 'The Basics of Digital Marketing', 11, 'READING', 'B1', 1.0, 'The Basics of Digital Marketing') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101111, 'Digital marketing is a form of marketing that uses digital channels such as search engines, social media, email, and websites to reach customers. It involves creating and sharing content that is relevant and valuable to your target audience, with the goal of driving website traffic, generating leads, and increasing sales. There are several key components of digital marketing, including search engine optimization (SEO), pay-per-click advertising (PPC), social media marketing, email marketing, and content marketing. By understanding these components and how they work together, businesses can create a comprehensive digital marketing strategy that helps them achieve their goals. For example, a company that sells outdoor gear might use SEO to optimize its website for search engines, PPC to run targeted ads on Google, and social media marketing to engage with customers on platforms like Facebook and Instagram.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100775, 101111, 'ROADMAP_QUIZ', 'What is digital marketing?', 'Marketing số là một hình thức tiếp thị sử dụng các kênh số như các công cụ tìm kiếm, mạng xã hội, email và trang web để tiếp cận khách hàng.', 'B1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100775, 'A', 'A form of marketing that uses traditional channels such as print and television.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100775, 'B', 'A form of marketing that uses digital channels such as search engines, social media, email, and websites.', true);
