INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100775, 'D', 'A form of marketing that only uses email.', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100776, 101111, 'ROADMAP_QUIZ', 'What are the key components of digital marketing?', 'Có một số thành phần chính của marketing số, bao gồm tối ưu hóa công cụ tìm kiếm (SEO), quảng cáo trả tiền mỗi lần nhấp chuột (PPC), tiếp thị trên mạng xã hội, tiếp thị qua email và tiếp thị nội dung.', 'B1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100776, 'A', 'SEO, PPC, social media marketing, email marketing, and content marketing.', true);
