INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101112, 'reading-b1-a-review-of-the-art-of-leadership', 1011, 'A Review of ''The Art of Leadership''', 12, 'READING', 'B1', 1.0, 'A Review of ''The Art of Leadership''') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101112, 'The Art of Leadership is a book written by a renowned business expert. The book provides insights into the qualities and skills required to become a successful leader. According to the author, a good leader must possess strong communication skills, be able to motivate their team members, and make informed decisions. The book also emphasizes the importance of adaptability, resilience, and empathy in leadership. The author shares real-life examples of successful leaders who have demonstrated these qualities and skills. Overall, the book is a valuable resource for anyone looking to improve their leadership skills and become a more effective leader.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100781, 101112, 'ROADMAP_QUIZ', 'What is the main topic of the book ''The Art of Leadership''?', 'Cuốn sách ''The Art of Leadership'' chủ yếu đề cập đến các phẩm chất và kỹ năng cần thiết để trở thành một nhà lãnh đạo thành công.', 'B1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100781, 'A', 'The qualities and skills required to become a successful leader', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100781, 'B', 'The importance of communication in business', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100781, 'C', 'The role of motivation in team management', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100781, 'D', 'The benefits of adaptability in leadership', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100782, 101112, 'ROADMAP_QUIZ', 'What is one of the key skills required to become a successful leader, according to the author?', 'Theo tác giả, một trong những kỹ năng quan trọng cần có để trở thành một nhà lãnh đạo thành công là kỹ năng giao tiếp mạnh mẽ.', 'B1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100782, 'A', 'Strong communication skills', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100782, 'B', 'Ability to make informed decisions', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100782, 'C', 'Ability to motivate team members', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100782, 'D', 'Ability to adapt to new situations', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100783, 101112, 'ROADMAP_QUIZ', 'What is the author''s approach to discussing leadership in the book?', 'Tác giả sử dụng những ví dụ thực tế để thảo luận về lãnh đạo trong cuốn sách.', 'B1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100783, 'A', 'Theoretical and abstract', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100783, 'B', 'Practical and real-life examples', true);
