INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100783, 'D', 'Philosophical and introspective', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100784, 101112, 'ROADMAP_QUIZ', 'What is one of the benefits of being a resilient leader, according to the author?', 'Theo tác giả, một trong những lợi ích của việc trở thành một nhà lãnh đạo kiên cường là khả năng xử lý căng thẳng và áp lực.', 'B1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100784, 'A', 'Ability to adapt to new situations', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100784, 'B', 'Ability to motivate team members', false);
