INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100784, 'D', 'Ability to handle stress and pressure', true);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100785, 101112, 'ROADMAP_QUIZ', 'What is the overall value of the book ''The Art of Leadership''?', 'Tổng thể, cuốn sách ''The Art of Leadership'' là một nguồn tài nguyên giá trị cho bất kỳ ai muốn cải thiện kỹ năng lãnh đạo.', 'B1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100785, 'A', 'A comprehensive guide to business management', false);
