INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101113, 'reading-b1-office-expansion-plan-announcement', 1011, 'Office Expansion Plan Announcement', 13, 'READING', 'B1', 1.0, 'Office Expansion Plan Announcement') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101113, 'Dear valued employees, we are pleased to announce that our company will be expanding its office space to accommodate our growing team. The new office will be located in a nearby building and will offer more amenities and services to enhance your work experience. The expansion plan includes the addition of new meeting rooms, a state-of-the-art gym, and a cafeteria serving a variety of healthy meals. We believe that this expansion will not only improve our working conditions but also boost our productivity and morale. The new office is expected to be completed by the end of the year, and we will keep you updated on the progress. Thank you for your hard work and dedication to our company. We look forward to seeing you in our new office soon.', 'Vietnamese Translation:
