INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101114, 'reading-b1-employee-of-the-month', 1011, 'Employee of the Month', 14, 'READING', 'B1', 1.0, 'Employee of the Month') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101114, 'Dear colleagues, we are pleased to announce that Emily Chen has been chosen as our Employee of the Month for April. Emily has been with our company for three years and has consistently demonstrated exceptional teamwork and dedication to her work. She is always willing to lend a hand and has been a valuable asset to our team. Emily''s hard work and commitment to excellence have not gone unnoticed, and we are grateful to have her on our team. Please join us in congratulating Emily on this well-deserved recognition.', 'Vietnamese Translation:
