INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101115, 'reading-b1-notice-of-website-terms-of-service-update', 1011, 'Notice of Website Terms of Service Update', 15, 'READING', 'B1', 1.0, 'Notice of Website Terms of Service Update') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101115, 'Dear valued customers, we are writing to inform you that our website''s terms of service will be updated on March 15th, 2024. The changes are designed to improve user experience and ensure compliance with new regulations. The updated terms will be effective immediately after the update. We recommend that you review the new terms carefully before continuing to use our website. If you have any questions or concerns, please do not hesitate to contact us. Thank you for your understanding and cooperation.', 'Vietnamese Translation:
