INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101116, 'reading-b1-employee-training-program-agenda', 1011, 'Employee Training Program Agenda', 16, 'READING', 'B1', 1.0, 'Employee Training Program Agenda') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101116, 'The employee training program agenda is as follows: 9:00-9:30am: Welcome and introduction to the training program. 9:30-10:30am: Presentation on time management skills. 10:30-10:50am: Break. 10:50am-12:00pm: Workshop on communication skills. 12:00-1:00pm: Lunch break. 1:00-2:30pm: Presentation on leadership skills. 2:30-3:00pm: Conclusion and evaluation of the training program.', 'Vietnamese Translation:
