INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101119, 'reading-b1-the-rise-of-eco-friendly-packaging', 1011, 'The Rise of Eco-Friendly Packaging', 19, 'READING', 'B1', 1.0, 'The Rise of Eco-Friendly Packaging') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101119, 'The world is slowly shifting towards a more sustainable future, and one of the key areas of focus is packaging. Traditional packaging methods have been criticized for their environmental impact, from plastic waste to carbon emissions. In response, companies are turning to eco-friendly packaging solutions that are not only better for the planet but also more cost-effective in the long run.
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100816, 101119, 'ROADMAP_QUIZ', 'Tại sao các công ty đang chuyển sang bao bì thân thiện với môi trường?', 'Các công ty đang chuyển sang bao bì thân thiện với môi trường để giảm thiểu rác thải và khí thải carbon, đồng thời cải thiện hình ảnh thương hiệu và sự trung thành của khách hàng.', 'B1') ON CONFLICT (id) DO NOTHING;
