INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101120, 'reading-b1-request-for-proposal-rfp-cover-letter', 1011, 'Request for Proposal (RFP) Cover Letter', 20, 'READING', 'B1', 1.0, 'Request for Proposal (RFP) Cover Letter') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101120, 'Dear Hiring Manager, We are pleased to submit our proposal for the project management services contract. Our team has extensive experience in managing large-scale projects and has a proven track record of delivering results on time and within budget. We believe that our expertise and commitment to quality make us an ideal partner for this project. We would welcome the opportunity to discuss our proposal in further detail and explain how we can meet your organization''s needs. Thank you for considering our proposal. Sincerely, [Your Name]', 'Vietnamese Translation:
