INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101501, 'reading-b2-quarterly-financial-performance-analysis-report', 1015, 'Quarterly Financial Performance Analysis Report', 1, 'READING', 'B2', 1.0, 'Quarterly Financial Performance Analysis Report') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101501, 'The quarterly financial performance analysis report for the second quarter of this year has been completed. According to the report, the company''s revenue has increased by 15% compared to the same period last year. The net profit has also risen by 20%, mainly due to the successful launch of new products. However, the report highlights some areas of concern, including a 10% decrease in sales in the Asian market. The company''s management team is currently reviewing the report and discussing strategies to address these issues. In the meantime, the company''s stock price has fluctuated, with some analysts predicting a further increase in the coming months.', 'Vietnamese Translation:
