INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101503, 'reading-b2-cybersecurity-in-modern-workplaces', 1015, 'Cybersecurity in Modern Workplaces', 3, 'READING', 'B2', 1.0, 'Cybersecurity in Modern Workplaces') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101503, 'The rapid growth of remote work has led to a significant increase in cybersecurity threats. As more employees work from home, companies are facing new challenges in protecting their data and systems. According to a recent survey, 70% of companies have experienced a cybersecurity breach in the past year. The most common types of attacks are phishing scams, ransomware, and malware. To combat these threats, companies are investing in advanced cybersecurity measures, such as artificial intelligence and machine learning. These technologies can detect and prevent cyber attacks in real-time, reducing the risk of data breaches. Additionally, companies are implementing robust security protocols, including multi-factor authentication and encryption. Employees are also being educated on cybersecurity best practices, such as using strong passwords and being cautious when clicking on links. By taking these steps, companies can protect their data and systems, and ensure the continued growth and success of their businesses.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100836, 101503, 'ROADMAP_QUIZ', 'Theo cuộc khảo sát gần đây, bao nhiêu phần trăm các công ty đã trải qua một vụ xâm nhập an ninh mạng trong năm qua?', 'Theo cuộc khảo sát gần đây, 70% các công ty đã trải qua một vụ xâm nhập an ninh mạng trong năm qua.', 'B2') ON CONFLICT (id) DO NOTHING;
