INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101504, 'reading-b2-commercial-real-estate-lease-agreement-excerpt', 1015, 'Commercial Real Estate Lease Agreement Excerpt', 4, 'READING', 'B2', 1.0, 'Commercial Real Estate Lease Agreement Excerpt') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101504, 'The commercial real estate lease agreement excerpt below outlines the terms and conditions of a 5-year lease for a 2,000 square foot office space. The tenant, XYZ Corporation, will pay an annual rent of $50,000, plus utilities and taxes. The landlord, ABC Properties, will be responsible for maintaining the common areas and providing access to the building''s amenities. The lease can be terminated early with a 6-month notice period. The tenant is also responsible for any damages caused to the property during the lease term.', 'Vietnamese Translation:
