INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101505, 'reading-b2-product-security-breach-a-major-concern', 1015, 'Product Security Breach: A Major Concern', 5, 'READING', 'B2', 1.0, 'Product Security Breach: A Major Concern') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101505, 'We are writing to inform you of a major security breach that occurred on our company''s servers. The breach, which was discovered on Tuesday evening, has compromised the personal data of over 10 million customers. We take the security of our customers'' data very seriously and are working closely with law enforcement to investigate the incident. We have already taken steps to contain the breach and prevent any further unauthorized access to our systems. We will be providing affected customers with a complimentary credit monitoring service to help protect their identities. We apologize for any inconvenience this may have caused and appreciate your patience and understanding during this time. We will continue to update you on the situation as more information becomes available.', 'Vietnamese Translation:
