INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101507, 'reading-b2-board-of-directors-meeting-summary-minutes', 1015, 'Board of Directors Meeting Summary Minutes', 7, 'READING', 'B2', 1.0, 'Board of Directors Meeting Summary Minutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101507, 'The Board of Directors meeting was held on March 12, 2023, at 9:00 a.m. in Conference Room A. The meeting was chaired by CEO, John Smith. The main agenda items discussed were the company''s financial performance, marketing strategies, and new product development. The financial performance review revealed a 10% increase in revenue compared to the same period last year. The marketing team presented their plans to launch a new social media campaign, which is expected to boost sales by 20%. The product development team reported on the progress of their new product, which is scheduled to be launched in the next quarter. The meeting concluded with a discussion on the company''s goals and objectives for the upcoming year. The next Board of Directors meeting is scheduled for June 15, 2023.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100857, 101507, 'ROADMAP_QUIZ', 'When was the Board of Directors meeting held?', 'Phiên họp Hội đồng quản trị đã được tổ chức vào ngày 12 tháng 3 năm 2023.', 'B2') ON CONFLICT (id) DO NOTHING;
