INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100857, 'D', 'September 10, 2023', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100858, 101507, 'ROADMAP_QUIZ', 'What was the main topic of discussion during the meeting?', 'Các mục chính được thảo luận bao gồm hiệu suất tài chính của công ty, chiến lược tiếp thị và phát triển sản phẩm mới.', 'B2') ON CONFLICT (id) DO NOTHING;
