INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101508, 'reading-b2-update-to-employee-code-of-conduct-ai-usage', 1015, 'Update to Employee Code of Conduct: AI Usage', 8, 'READING', 'B2', 1.0, 'Update to Employee Code of Conduct: AI Usage') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101508, 'Dear employees, as we continue to integrate artificial intelligence (AI) into our daily operations, it is essential that we establish clear guidelines for its use. The purpose of this update to our Employee Code of Conduct is to provide a framework for responsible AI usage and to ensure that we maintain the highest standards of integrity and professionalism in our work. The updated code of conduct includes the following key points: AI systems must be used in accordance with their intended purpose and must not be used for personal gain or to compromise company data. Employees are expected to report any instances of AI misuse or suspected security breaches to their supervisor or the IT department immediately. Failure to comply with this code of conduct may result in disciplinary action, up to and including termination of employment. We appreciate your cooperation and commitment to upholding our company''s values and standards. If you have any questions or concerns, please do not hesitate to reach out to your supervisor or HR representative.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100862, 101508, 'ROADMAP_QUIZ', 'Mục đích của bản cập nhật này về Quy tắc Hành vi của Nhân viên là gì?', 'Bản cập nhật này về Quy tắc Hành vi của Nhân viên được thiết kế để cung cấp một khung khổ cho việc sử dụng AI một cách có trách nhiệm và đảm bảo rằng nhân viên tuân thủ các quy định về bảo mật.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100862, 'A', 'Để thiết lập các quy định rõ ràng về việc sử dụng AI', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100862, 'B', 'Để cung cấp một khung khổ cho việc sử dụng AI một cách có trách nhiệm', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100862, 'C', 'Để đảm bảo rằng nhân viên tuân thủ các quy định về bảo mật', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100862, 'D', 'Để tăng cường kỷ luật trong công ty', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100863, 101508, 'ROADMAP_QUIZ', 'Ai được yêu cầu báo cáo các trường hợp lạm dụng AI?', 'Tất cả các nhân viên được yêu cầu báo cáo các trường hợp lạm dụng AI hoặc nghi ngờ về các cuộc tấn công bảo mật đến người quản lý hoặc bộ phận IT.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100863, 'A', 'Người quản lý', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100863, 'B', 'Bộ phận IT', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100863, 'C', 'Nhân viên', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100863, 'D', 'Tất cả các lựa chọn trên', true);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100864, 101508, 'ROADMAP_QUIZ', 'Hậu quả của việc không tuân thủ Quy tắc Hành vi của Nhân viên là gì?', 'Hậu quả của việc không tuân thủ Quy tắc Hành vi của Nhân viên có thể bao gồm kỷ luật nghiêm trọng, sa thải hoặc các biện pháp kỷ luật khác.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100864, 'A', 'Kỷ luật nhẹ', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100864, 'B', 'Kỷ luật nghiêm trọng', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100864, 'C', 'Sa thải', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100864, 'D', 'Tất cả các lựa chọn trên', true);
INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101509, 'reading-b2-renewable-energy-integration-a-path-to-sustainability', 1015, 'Renewable Energy Integration: A Path to Sustainability', 9, 'READING', 'B2', 1.0, 'Renewable Energy Integration: A Path to Sustainability') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101509, 'The integration of renewable energy sources into the global energy mix is a crucial step towards achieving sustainability. As the world grapples with the challenges of climate change, energy security, and economic development, the transition to renewable energy has become increasingly important. Renewable energy sources such as solar, wind, and hydroelectric power offer a cleaner and more sustainable alternative to fossil fuels. However, the integration of these sources into the existing energy infrastructure poses significant technical, economic, and policy challenges. To overcome these challenges, governments, industries, and civil society must work together to develop and implement policies and technologies that support the widespread adoption of renewable energy. This whitepaper provides an overview of the current state of renewable energy integration and identifies key areas for further research and development.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100865, 101509, 'ROADMAP_QUIZ', 'What is the main goal of integrating renewable energy sources into the global energy mix?', 'Mục tiêu chính của việc tích hợp nguồn năng lượng tái tạo vào hỗn hợp năng lượng toàn cầu là đạt được sự bền vững.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100865, 'A', 'To reduce greenhouse gas emissions', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100865, 'B', 'To increase energy security', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100865, 'C', 'To promote economic development', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100865, 'D', 'To achieve sustainability', true);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100866, 101509, 'ROADMAP_QUIZ', 'What are some of the challenges associated with integrating renewable energy sources into the existing energy infrastructure?', 'Một số thách thức liên quan đến việc tích hợp nguồn năng lượng tái tạo vào cơ sở hạ tầng năng lượng hiện có bao gồm thách thức kỹ thuật, kinh tế và chính sách.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100866, 'A', 'Technical, economic, and policy challenges', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100866, 'B', 'Only technical challenges', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100866, 'C', 'Only economic challenges', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100866, 'D', 'Only policy challenges', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100867, 101509, 'ROADMAP_QUIZ', 'Who must work together to develop and implement policies and technologies that support the widespread adoption of renewable energy?', 'Chính phủ, ngành công nghiệp và xã hội dân sự phải hợp tác để phát triển và thực hiện các chính sách và công nghệ hỗ trợ việc áp dụng rộng rãi năng lượng tái tạo.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100867, 'A', 'Governments and industries', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100867, 'B', 'Civil society and industries', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100867, 'C', 'Governments, industries, and civil society', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100867, 'D', 'Only civil society', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100868, 101509, 'ROADMAP_QUIZ', 'What is the purpose of this whitepaper?', 'Mục đích của bài viết này là cung cấp một cái nhìn tổng quan về tình hình hiện tại của việc tích hợp năng lượng tái tạo.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100868, 'A', 'To provide an overview of the current state of renewable energy integration', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100868, 'B', 'To identify key areas for further research and development', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100868, 'C', 'To promote the use of fossil fuels', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100868, 'D', 'To reduce energy consumption', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100869, 101509, 'ROADMAP_QUIZ', 'What are some of the benefits of renewable energy sources?', 'Một số lợi ích của nguồn năng lượng tái tạo bao gồm nguồn năng lượng sạch và bền vững hơn so với nhiên liệu hóa thạch.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100869, 'A', 'Cleaner and more sustainable alternative to fossil fuels', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100869, 'B', 'Higher energy costs', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100869, 'C', 'Lower energy efficiency', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100869, 'D', 'Increased greenhouse gas emissions', false);
INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101510, 'reading-b2-strategic-joint-venture-proposal', 1015, 'Strategic Joint Venture Proposal', 10, 'READING', 'B2', 1.0, 'Strategic Joint Venture Proposal') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101510, 'We are pleased to submit our proposal for a strategic joint venture between our company, GreenTech Inc., and your esteemed organization, ABC Corporation. Our proposal outlines a comprehensive plan for a mutually beneficial partnership that will drive growth, innovation, and profitability for both parties.
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100870, 101510, 'ROADMAP_QUIZ', 'What is the main focus of the proposed joint venture?', 'Đơn đề xuất của GreenTech Inc. đề xuất liên doanh sẽ tập trung vào việc phát triển và tiếp thị các giải pháp năng lượng tái tạo tiên tiến.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100870, 'A', 'Developing and marketing cutting-edge technology', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100870, 'B', 'Establishing a joint research and development center', false);
