INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101511, 'reading-b2-creating-a-culture-of-psychological-safety', 1015, 'Creating a Culture of Psychological Safety', 11, 'READING', 'B2', 1.0, 'Creating a Culture of Psychological Safety') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101511, 'In today''s fast-paced corporate world, psychological safety is becoming increasingly important for teams to thrive. It refers to the feeling of security and freedom to express oneself without fear of judgment or retribution. When team members feel psychologically safe, they are more likely to share their ideas, take risks, and collaborate effectively.
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100875, 101511, 'ROADMAP_QUIZ', 'Psychological safety là gì?', 'An toàn tâm lý là cảm giác an toàn và tự do để thể hiện bản thân mà không sợ bị phán xét hoặc trừng phạt.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100875, 'A', 'Một loại hình thức an toàn vật chất', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100875, 'B', 'Một loại hình thức an toàn tâm lý', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100875, 'C', 'Một loại hình thức an toàn xã hội', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100875, 'D', 'Một loại hình thức an toàn môi trường', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100876, 101511, 'ROADMAP_QUIZ', 'Tại sao các nhóm có an toàn tâm lý cao hơn sẽ sản xuất nhiều hơn?', 'Các nhóm có an toàn tâm lý cao hơn sẽ có khả năng thể hiện bản thân và chia sẻ ý tưởng mà không sợ bị phán xét hoặc trừng phạt.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100876, 'A', 'Bởi vì họ có nhiều nguồn lực hơn', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100876, 'B', 'Bởi vì họ có nhiều kỹ năng hơn', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100876, 'C', 'Bởi vì họ có nhiều ý tưởng hơn', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100876, 'D', 'Bởi vì họ có nhiều tự do hơn để thể hiện bản thân', true);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100877, 101511, 'ROADMAP_QUIZ', 'Cách nào để các nhà lãnh đạo tạo ra một nền văn hóa an toàn tâm lý trong các nhóm của mình?', 'Các nhà lãnh đạo có thể tạo ra một nền văn hóa an toàn tâm lý bằng cách khuyến khích giao tiếp mở và lắng nghe tích cực.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100877, 'A', 'Bằng cách áp dụng các quy định nghiêm ngặt', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100877, 'B', 'Bằng cách khuyến khích giao tiếp mở', true);
