INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100878, 'A', 'Bởi vì họ muốn tạo ra một nền văn hóa an toàn tâm lý', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100878, 'B', 'Bởi vì họ muốn khuyến khích sáng tạo và hợp tác', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100878, 'C', 'Bởi vì họ muốn tạo ra một môi trường làm việc tích cực', true);
