INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101512, 'reading-b2-annual-corporate-social-responsibility-csr-report', 1015, 'Annual Corporate Social Responsibility (CSR) Report', 12, 'READING', 'B2', 1.0, 'Annual Corporate Social Responsibility (CSR) Report') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101512, 'Our company is committed to making a positive impact on the environment and the communities we serve. As part of our corporate social responsibility (CSR) efforts, we have implemented various initiatives to reduce our carbon footprint and promote sustainability. In our annual CSR report, we highlight our achievements and progress towards our goals. This year, we have achieved a 25% reduction in energy consumption and a 30% reduction in waste production. We have also implemented a new recycling program and partnered with local organizations to support community development projects. Our CSR report provides a detailed account of our activities and the impact we have made. We believe that our CSR efforts are essential to creating a better future for our stakeholders and the environment.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100880, 101512, 'ROADMAP_QUIZ', 'Mục tiêu chính của báo cáo CSR hàng năm của công ty là gì?', 'Báo cáo CSR hàng năm của công ty cung cấp thông tin chi tiết về các hoạt động và tác động của công ty, bao gồm cả tiến bộ và thành tựu.', 'B2') ON CONFLICT (id) DO NOTHING;
