INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101513, 'reading-b2-project-risk-assessment-and-mitigation-plan', 1015, 'Project Risk Assessment and Mitigation Plan', 13, 'READING', 'B2', 1.0, 'Project Risk Assessment and Mitigation Plan') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101513, 'The project team has identified several potential risks that could impact the success of the new product launch. These risks include delays in production, changes in market demand, and issues with the supply chain. To mitigate these risks, the team has developed a comprehensive risk assessment and mitigation plan. The plan includes regular meetings with suppliers to ensure timely delivery of materials, a flexible production schedule to accommodate changes in demand, and a contingency plan in case of unexpected delays. The team will also conduct regular risk assessments to identify and address any new risks that may arise. By taking a proactive approach to risk management, the team is confident that the new product launch will be a success.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100885, 101513, 'ROADMAP_QUIZ', 'What are the potential risks that could impact the success of the new product launch?', 'Đội ngũ dự án đã xác định được một số rủi ro tiềm ẩn có thể ảnh hưởng đến thành công của việc ra mắt sản phẩm mới, bao gồm trì hoãn sản xuất, thay đổi nhu cầu thị trường và vấn đề với chuỗi cung ứng.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100885, 'A', 'Delays in production and changes in market demand', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100885, 'B', 'Issues with the supply chain and a lack of funding', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100885, 'C', 'Delays in production, changes in market demand, and issues with the supply chain', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100885, 'D', 'A lack of funding and a lack of resources', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100886, 101513, 'ROADMAP_QUIZ', 'What is the purpose of the risk assessment and mitigation plan?', 'Kế hoạch đánh giá và giảm thiểu rủi ro được phát triển để xác định và giải quyết bất kỳ rủi ro mới nào có thể phát sinh.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100886, 'A', 'To identify and address new risks that may arise', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100886, 'B', 'To ensure timely delivery of materials', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100886, 'C', 'To accommodate changes in demand', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100886, 'D', 'To reduce the risk of delays in production', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100887, 101513, 'ROADMAP_QUIZ', 'What is the team''s approach to risk management?', 'Đội ngũ tiếp cận chủ động đối với quản lý rủi ro, bằng cách thực hiện các đánh giá rủi ro thường xuyên và phát triển kế hoạch dự phòng.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100887, 'A', 'Passive', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100887, 'B', 'Proactive', true);
