INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100911, 'D', 'Sai sót trong quá trình lập hồ sơ', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100912, 101518, 'ROADMAP_QUIZ', 'Công ty đã thực hiện các hành động khắc phục nào để giải quyết các sai sót trong hồ sơ tài chính?', 'Công ty đã thực hiện các hành động khắc phục bao gồm thực hiện hệ thống kiểm soát nội bộ mới, thực hiện các cuộc kiểm toán thường xuyên và thực hiện các cuộc đánh giá thường xuyên.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100912, 'A', 'Thực hiện hệ thống kiểm soát nội bộ mới', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100912, 'B', 'Thực hiện các cuộc kiểm toán thường xuyên', false);
