INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100914, 101518, 'ROADMAP_QUIZ', 'Hệ thống kiểm soát nội bộ mới của công ty sẽ được thực hiện đầy đủ trong bao lâu?', 'Hệ thống kiểm soát nội bộ mới của công ty được dự kiến sẽ được thực hiện đầy đủ trong sáu tháng tới.', 'B2') ON CONFLICT (id) DO NOTHING;
