INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100915, 101518, 'ROADMAP_QUIZ', 'Ban quản lý của công ty cam kết điều gì?', 'Ban quản lý của công ty cam kết minh bạch và trách nhiệm và đang làm việc để xây dựng lại niềm tin với các bên liên quan.', 'B2') ON CONFLICT (id) DO NOTHING;
