INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101519, 'reading-b2-talent-retention-strategies-post-pandemic', 1015, 'Talent Retention Strategies Post-Pandemic', 19, 'READING', 'B2', 1.0, 'Talent Retention Strategies Post-Pandemic') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101519, 'The COVID-19 pandemic has had a profound impact on the global workforce. With many employees working remotely, companies have had to adapt to new ways of managing their teams. One of the key challenges facing organizations is talent retention. With the rise of remote work, employees have more flexibility and autonomy than ever before. This has led to a shift in the way companies approach talent retention. In this article, we will explore some of the strategies that companies can use to retain their top talent in a post-pandemic world.
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100916, 101519, 'ROADMAP_QUIZ', 'What has been the impact of the COVID-19 pandemic on the global workforce?', 'Dịch COVID-19 đã có tác động sâu sắc đến lực lượng lao động toàn cầu.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100916, 'A', 'It has led to a decrease in remote work', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100916, 'B', 'It has had a profound impact on the global workforce', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100916, 'C', 'It has led to an increase in office work', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100916, 'D', 'It has had no impact on the global workforce', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100917, 101519, 'ROADMAP_QUIZ', 'What is one of the key challenges facing organizations in a post-pandemic world?', 'Một trong những thách thức chính mà các tổ chức phải đối mặt là giữ chân nhân tài.', 'B2') ON CONFLICT (id) DO NOTHING;
