INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100917, 'D', 'Customer satisfaction', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100918, 101519, 'ROADMAP_QUIZ', 'What should companies do to support remote work?', 'Các công ty nên cung cấp cho nhân viên các công cụ và tài nguyên cần thiết để làm việc hiệu quả từ xa.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100918, 'A', 'Force employees back into the office', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100918, 'B', 'Create a culture that supports remote work', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100918, 'C', 'Provide employees with the tools and resources they need to work effectively from home', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100918, 'D', 'None of the above', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100919, 101519, 'ROADMAP_QUIZ', 'What is one of the ways companies can prioritize employee well-being?', 'Một trong những cách mà các công ty có thể ưu tiên sức khỏe của nhân viên là cung cấp các nguồn lực sức khỏe tinh thần, các thỏa thuận làm việc linh hoạt và truy cập các lớp tập thể dục.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100919, 'A', 'Offering mental health resources', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100919, 'B', 'Flexible work arrangements', false);
