INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100919, 'D', 'All of the above', true);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100920, 101519, 'ROADMAP_QUIZ', 'Why is it important for companies to be transparent and communicative?', 'Tại sao các công ty cần phải minh bạch và giao tiếp? Vì nó giúp xây dựng niềm tin với nhân viên.', 'B2') ON CONFLICT (id) DO NOTHING;
