INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101520, 'reading-b2-request-for-quote-rfq-technical-specifications', 1015, 'Request for Quote (RFQ) Technical Specifications', 20, 'READING', 'B2', 1.0, 'Request for Quote (RFQ) Technical Specifications') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101520, 'The following technical specifications are required for the RFQ for the supply of a new water treatment plant. The plant will be used to supply drinking water to a population of 50,000 people. The plant will be located in a coastal area and will require a seawater intake system. The plant will also require a reverse osmosis system to remove salt and other impurities from the water. The plant will have a capacity of 20,000 cubic meters per day. The plant will be designed to operate 24 hours a day, 7 days a week. The plant will require a power supply of 500 kW. The plant will also require a control system to monitor and control the treatment process. The control system will include a SCADA system, a programmable logic controller (PLC), and a human-machine interface (HMI). The plant will require a maintenance schedule to ensure that it operates efficiently and effectively. The maintenance schedule will include regular cleaning and replacement of filters, as well as regular testing of the plant''s equipment.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100921, 101520, 'ROADMAP_QUIZ', 'What is the purpose of the water treatment plant?', 'Nhà máy xử lý nước sẽ được sử dụng để cung cấp nước uống cho dân số 50.000 người.', 'B2') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100921, 'A', 'To supply drinking water to a population of 10,000 people', false);
