INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101901, 'reading-c1-evaluating-the-impact-of-climate-change-on-global-food-security', 1019, 'Evaluating the Impact of Climate Change on Global Food Security', 1, 'READING', 'C1', 1.0, 'Evaluating the Impact of Climate Change on Global Food Security') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101901, 'Climate change is having a profound impact on global food security, with rising temperatures and changing precipitation patterns affecting crop yields and food availability. A recent study published in the journal Nature estimated that climate change could lead to a 2% decline in global crop yields by 2030, resulting in food price increases and reduced access to nutritious food for millions of people. The study''s authors recommend that policymakers prioritize climate-resilient agricultural practices, such as agroforestry and conservation agriculture, to mitigate the effects of climate change on food security. Additionally, they suggest that governments invest in climate information services to help farmers make informed decisions about planting and harvesting. By taking these steps, we can reduce the risks associated with climate change and ensure that everyone has access to sufficient, safe, and nutritious food.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100927, 101901, 'ROADMAP_QUIZ', 'Climate change is expected to have what impact on global crop yields by 2030?', 'Thay đổi khí hậu dự kiến sẽ có tác động gì đến sản lượng cây trồng toàn cầu vào năm 2030?', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100927, 'A', 'A 1% increase', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100927, 'B', 'A 2% decline', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100927, 'C', 'No impact', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100927, 'D', 'A 5% increase', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100928, 101901, 'ROADMAP_QUIZ', 'What do the study''s authors recommend policymakers prioritize?', 'Các tác giả của nghiên cứu đề xuất chính sách nào mà chính phủ nên ưu tiên?', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100928, 'A', 'Climate-resilient agricultural practices', true);
