INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101902, 'reading-c1-a-diplomatic-policy-brief', 1019, 'A Diplomatic Policy Brief', 2, 'READING', 'C1', 1.0, 'A Diplomatic Policy Brief') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101902, 'The recent escalation of tensions between the United States and North Korea has led to a renewed focus on diplomatic efforts to resolve the crisis. The US government has been working closely with its allies in the region, including South Korea and Japan, to develop a unified strategy for dealing with the North Korean threat. Meanwhile, the international community has been calling for restraint and diplomacy, with many countries urging the US and North Korea to engage in direct talks. In this context, the role of diplomacy in resolving international conflicts has become increasingly important. Diplomacy can take many forms, including negotiations, mediation, and economic incentives. In the case of the US-North Korea crisis, diplomacy has been used to try to persuade North Korea to abandon its nuclear program in exchange for economic aid and security guarantees. However, the effectiveness of diplomacy in resolving this crisis remains to be seen. Some experts argue that diplomacy is the only viable option for resolving the crisis, while others believe that military action may be necessary to protect US interests. As the situation continues to unfold, it is clear that diplomacy will play a crucial role in determining the outcome.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100932, 101902, 'ROADMAP_QUIZ', 'What has led to a renewed focus on diplomatic efforts to resolve the crisis?', 'Tình hình căng thẳng giữa Mỹ và Triều Tiên đã dẫn đến sự tập trung lại vào các nỗ lực ngoại giao để giải quyết khủng hoảng.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100932, 'A', 'The US government''s decision to withdraw from the region', false);
