INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100932, 'C', 'The international community''s call for restraint and diplomacy', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100932, 'D', 'The South Korean government''s decision to engage in direct talks with North Korea', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100933, 101902, 'ROADMAP_QUIZ', 'What is the role of diplomacy in resolving international conflicts?', 'Ngoại giao có thể có nhiều hình thức, bao gồm đàm phán, trung gian và các biện pháp khuyến khích kinh tế.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100933, 'A', 'To use military force to protect national interests', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100933, 'B', 'To persuade countries to abandon their nuclear programs', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100933, 'C', 'To negotiate and mediate between countries', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100933, 'D', 'To provide economic aid to countries in need', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100934, 101902, 'ROADMAP_QUIZ', 'What is the US government''s strategy for dealing with the North Korean threat?', 'Chính phủ Mỹ đã làm việc chặt chẽ với các đồng minh của mình trong khu vực, bao gồm Hàn Quốc và Nhật Bản, để phát triển một chiến lược thống nhất cho việc đối phó với mối đe dọa của Triều Tiên.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100934, 'A', 'To use economic incentives to persuade North Korea to abandon its nuclear program', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100934, 'B', 'To engage in direct talks with North Korea', false);
