INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100934, 'D', 'To withdraw from the region', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100935, 101902, 'ROADMAP_QUIZ', 'What is the international community''s stance on the US-North Korea crisis?', 'Cộng đồng quốc tế đã kêu gọi sự kiềm chế và ngoại giao, với nhiều quốc gia khuyên Mỹ và Triều Tiên nên tham gia vào các cuộc đàm phán trực tiếp.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100935, 'A', 'To support the US government''s decision to withdraw from the region', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100935, 'B', 'To call for restraint and diplomacy', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100935, 'C', 'To urge the US and North Korea to engage in direct talks', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100935, 'D', 'To provide economic aid to North Korea', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100936, 101902, 'ROADMAP_QUIZ', 'What is the effectiveness of diplomacy in resolving the US-North Korea crisis?', 'Hiệu quả của ngoại giao trong việc giải quyết khủng hoảng này vẫn còn phải được xem xét.', 'C1') ON CONFLICT (id) DO NOTHING;
