INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101903, 'reading-c1-the-shift-to-a-service-based-economy', 1019, 'The Shift to a Service-Based Economy', 3, 'READING', 'C1', 1.0, 'The Shift to a Service-Based Economy') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101903, 'The world is undergoing a significant macro-economic shift, driven by the increasing demand for services over goods. This trend is being fueled by the growing middle class in emerging markets, who are seeking higher-quality, more personalized experiences. As a result, companies are being forced to adapt their business models to meet this new demand.
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100937, 101903, 'ROADMAP_QUIZ', 'What is driving the shift to a service-based economy?', 'Sự tăng trưởng của tầng lớp trung lưu ở các thị trường mới nổi đang thúc đẩy nhu cầu ngày càng tăng về dịch vụ.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100937, 'A', 'The increasing demand for goods', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100937, 'B', 'The growing middle class in emerging markets', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100937, 'C', 'The rise of technology', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100937, 'D', 'The decline of traditional industries', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100938, 101903, 'ROADMAP_QUIZ', 'What is an example of a company adapting to the shift to a service-based economy?', 'Bệnh viện đang cung cấp nhiều dịch vụ toàn diện hơn, bao gồm các chương trình sức khỏe và hỗ trợ tâm lý.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100938, 'A', 'A hospital that only provides medical treatment', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100938, 'B', 'A hospital that offers holistic services, including wellness programs and mental health support', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100938, 'C', 'A company that only sells goods online', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100938, 'D', 'A company that only provides customer service via phone', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100939, 101903, 'ROADMAP_QUIZ', 'What is a key implication of the shift to a service-based economy?', 'Khi nền kinh tế trở nên dựa nhiều hơn vào dịch vụ, chính phủ sẽ cần tập trung vào việc tạo ra một môi trường hỗ trợ sáng tạo và khởi nghiệp.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100939, 'A', 'Governments will need to focus on creating an environment that supports innovation and entrepreneurship', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100939, 'B', 'Companies will need to reduce their workforce', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100939, 'C', 'The economy will become more goods-oriented', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100939, 'D', 'The service sector will decline', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100940, 101903, 'ROADMAP_QUIZ', 'What is an example of a new value proposition in the education sector?', 'Các tổ chức giáo dục đang chuyển khỏi các phương pháp giảng dạy truyền thống và hướng tới các phương pháp học tập trải nghiệm hơn.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100940, 'A', 'Traditional teaching methods', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100940, 'B', 'Experiential learning approaches, including hands-on training and project-based learning', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100940, 'C', 'Online courses that cater to different learning styles', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100940, 'D', 'A combination of all the above', true);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100941, 101903, 'ROADMAP_QUIZ', 'What is the overall impact of the shift to a service-based economy?', 'Sự chuyển đổi sang một nền kinh tế dựa trên dịch vụ là một cơ hội để tạo ra các đề xuất giá trị mới, thúc đẩy tăng trưởng và cải thiện chất lượng cuộc sống cho người dân trên toàn thế giới.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100941, 'A', 'It will lead to a decline in the quality of life for people around the world', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100941, 'B', 'It will create new opportunities for growth and improvement in the quality of life', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100941, 'C', 'It will have no impact on the quality of life', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100941, 'D', 'It will lead to a shift in the global economy', false);
INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101904, 'reading-c1-the-supreme-court-ruling-on-corporate-liability', 1019, 'The Supreme Court Ruling on Corporate Liability', 4, 'READING', 'C1', 1.0, 'The Supreme Court Ruling on Corporate Liability') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101904, 'In a landmark decision, the Supreme Court has ruled that corporations can be held liable for human rights abuses committed by their subsidiaries. The court''s majority opinion, written by Justice Smith, states that corporations have a duty to ensure that their subsidiaries comply with international human rights standards. This ruling has significant implications for multinational corporations operating in countries with poor human rights records. The court''s decision was met with praise from human rights groups, who argue that it will help to hold corporations accountable for their actions. However, some critics argue that the ruling goes too far, and that it will stifle economic growth by imposing unnecessary regulatory burdens on businesses. The court''s ruling is also seen as a victory for the victims of human rights abuses, who will now have a clearer path to seeking justice. As one human rights activist noted, ''This ruling is a major step forward for human rights, and it sends a powerful message to corporations that they cannot ignore their responsibilities.''', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100942, 101904, 'ROADMAP_QUIZ', 'Theo quyết định của Tòa án Tối cao, các công ty có thể bị truy cứu trách nhiệm hình sự về các tội ác nhân quyền được thực hiện bởi:', 'Theo quyết định của Tòa án Tối cao, các công ty có thể bị truy cứu trách nhiệm hình sự về các tội ác nhân quyền được thực hiện bởi các chi nhánh của họ.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100942, 'A', 'Các chi nhánh của họ', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100942, 'B', 'Các đối tác kinh doanh của họ', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100942, 'C', 'Các nhân viên của họ', false);
