INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100943, 101904, 'ROADMAP_QUIZ', 'Quyết định của Tòa án Tối cao có ý nghĩa quan trọng đối với:', 'Quyết định của Tòa án Tối cao có ý nghĩa quan trọng đối với các công ty đa quốc gia hoạt động ở các quốc gia có hồ sơ nhân quyền kém.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100943, 'A', 'Các công ty đa quốc gia hoạt động ở các quốc gia có hồ sơ nhân quyền kém', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100943, 'B', 'Các tổ chức nhân quyền', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100943, 'C', 'Các doanh nghiệp nhỏ', false);
