INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100944, 101904, 'ROADMAP_QUIZ', 'Theo quyết định của Tòa án Tối cao, các công ty có nghĩa vụ:', 'Theo quyết định của Tòa án Tối cao, các công ty có nghĩa vụ đảm bảo rằng các chi nhánh của họ tuân thủ các tiêu chuẩn nhân quyền quốc tế.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100944, 'A', 'Đảm bảo rằng các chi nhánh của họ tuân thủ các tiêu chuẩn nhân quyền quốc tế', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100944, 'B', 'Đảm bảo rằng các đối tác kinh doanh của họ tuân thủ các tiêu chuẩn nhân quyền quốc tế', false);
