INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101905, 'reading-c1-a-comprehensive-meta-analysis-summary', 1019, 'A Comprehensive Meta-Analysis Summary', 5, 'READING', 'C1', 1.0, 'A Comprehensive Meta-Analysis Summary') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101905, 'A recent meta-analysis published in the Journal of Clinical Epidemiology has provided a comprehensive summary of the effects of exercise on cardiovascular disease. The study, which pooled data from 17 randomized controlled trials, found that regular exercise significantly reduces the risk of cardiovascular disease in both men and women. The analysis also revealed that the benefits of exercise on cardiovascular health are dose-dependent, with greater reductions in risk observed with higher levels of physical activity. Furthermore, the study found that exercise has a positive impact on mental health, with regular physical activity associated with lower levels of anxiety and depression. The findings of this meta-analysis have important implications for public health policy and practice, highlighting the need for increased investment in physical activity programs and infrastructure. As the World Health Organization has noted, physical inactivity is a major risk factor for non-communicable diseases, and increasing physical activity levels is a key strategy for reducing the burden of these diseases.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100947, 101905, 'ROADMAP_QUIZ', 'What type of study was conducted to investigate the effects of exercise on cardiovascular disease?', 'Phân tích tổng hợp là một phương pháp nghiên cứu tổng hợp dữ liệu từ nhiều nghiên cứu khác nhau để tìm kiếm kết quả tổng thể.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100947, 'A', 'A survey', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100947, 'B', 'A meta-analysis', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100947, 'C', 'A randomized controlled trial', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100947, 'D', 'A case study', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100948, 101905, 'ROADMAP_QUIZ', 'What was the main finding of the meta-analysis regarding the relationship between exercise and cardiovascular disease?', 'Phân tích tổng hợp đã tìm thấy rằng tập thể dục đều đặn giảm đáng kể nguy cơ bệnh tim mạch.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100948, 'A', 'Exercise has no effect on cardiovascular disease', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100948, 'B', 'Exercise increases the risk of cardiovascular disease', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100948, 'C', 'Exercise reduces the risk of cardiovascular disease', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100948, 'D', 'Exercise has no impact on cardiovascular health', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100949, 101905, 'ROADMAP_QUIZ', 'What is the relationship between exercise and mental health according to the meta-analysis?', 'Phân tích tổng hợp đã tìm thấy rằng tập thể dục đều đặn liên quan đến mức độ lo lắng và trầm cảm thấp hơn.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100949, 'A', 'Exercise has a negative impact on mental health', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100949, 'B', 'Exercise has no impact on mental health', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100949, 'C', 'Exercise has a positive impact on mental health', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100949, 'D', 'Exercise increases anxiety and depression', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100950, 101905, 'ROADMAP_QUIZ', 'What is the implication of the meta-analysis for public health policy and practice?', 'Phân tích tổng hợp đã nhấn mạnh nhu cầu đầu tư tăng cường vào các chương trình và cơ sở vật chất tập thể dục.', 'C1') ON CONFLICT (id) DO NOTHING;
