INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101906, 'reading-c1-the-ethics-of-modern-technology', 1019, 'The Ethics of Modern Technology', 6, 'READING', 'C1', 1.0, 'The Ethics of Modern Technology') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101906, 'The advent of modern technology has brought about unprecedented changes in the way we live and interact with one another. On one hand, it has enabled us to communicate with people across the globe in real-time, access vast amounts of information, and automate many mundane tasks. However, it has also raised important questions about the ethics of our actions in the digital age.
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100952, 101906, 'ROADMAP_QUIZ', 'What is the main concern of the author regarding modern technology?', 'Tác giả quan tâm chính của tác giả về công nghệ hiện đại là vấn đề bảo mật.', 'C1') ON CONFLICT (id) DO NOTHING;
