INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101908, 'reading-c1-a-critical-analysis-of-james-joyces-ulysses', 1019, 'A Critical Analysis of James Joyce''s Ulysses', 8, 'READING', 'C1', 1.0, 'A Critical Analysis of James Joyce''s Ulysses') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101908, 'James Joyce''s Ulysses is a novel that has been the subject of much debate and analysis since its publication in 1922. On the surface, the novel appears to be a simple tale of a man''s journey through Dublin, but upon closer inspection, it reveals itself to be a complex and multifaceted work of literature. One of the key themes of the novel is the concept of identity, and how it is shaped by our experiences and interactions with the world around us. Through the character of Leopold Bloom, Joyce explores the idea that identity is not fixed, but rather is constantly evolving and changing. This is reflected in the novel''s use of stream-of-consciousness narration, which allows the reader to experience the world through Bloom''s eyes and gain a deeper understanding of his thoughts and feelings. Another key theme of the novel is the concept of nationality and how it is tied to identity. Through Bloom''s experiences as a Jewish man living in Ireland, Joyce highlights the tensions and conflicts that can arise between different cultural and national identities. Overall, Ulysses is a novel that challenges the reader to think critically about the nature of identity and how it is shaped by our experiences and interactions with the world around us.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100962, 101908, 'ROADMAP_QUIZ', 'What is the main theme of James Joyce''s Ulysses?', 'Chủ đề chính của tiểu thuyết Ulysses của James Joyce là khái niệm về bản sắc và cách nó được hình thành bởi những trải nghiệm và tương tác của chúng ta với thế giới xung quanh.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100962, 'A', 'The struggle for independence in Ireland', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100962, 'B', 'The concept of identity and how it is shaped by our experiences and interactions with the world around us', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100962, 'C', 'The importance of nationality and how it is tied to identity', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100962, 'D', 'The role of literature in shaping our understanding of the world', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100963, 101908, 'ROADMAP_QUIZ', 'How does the novel''s use of stream-of-consciousness narration contribute to the reader''s understanding of the character of Leopold Bloom?', 'Sử dụng thể loại kể chuyện dòng ý thức trong tiểu thuyết cho phép người đọc trải nghiệm thế giới thông qua mắt của Bloom và có được một hiểu biết sâu sắc hơn về suy nghĩ và cảm xúc của ông.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100963, 'A', 'It allows the reader to experience the world through Bloom''s eyes, gaining a deeper understanding of his thoughts and feelings', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100963, 'B', 'It provides a detailed description of Bloom''s physical appearance', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100963, 'C', 'It offers a critical analysis of Bloom''s actions and decisions', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100963, 'D', 'It ignores Bloom''s thoughts and feelings altogether', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100964, 101908, 'ROADMAP_QUIZ', 'What is the significance of the character of Leopold Bloom in the novel?', 'Nhân vật Leopold Bloom đại diện cho khái niệm về bản sắc và cách nó được hình thành bởi những trải nghiệm và tương tác của chúng ta với thế giới xung quanh.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100964, 'A', 'He represents the struggle for independence in Ireland', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100964, 'B', 'He embodies the concept of identity and how it is shaped by our experiences and interactions with the world around us', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100964, 'C', 'He symbolizes the importance of nationality and how it is tied to identity', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100964, 'D', 'He is a minor character with no significant role in the novel', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100965, 101908, 'ROADMAP_QUIZ', 'What is the author''s purpose in exploring the theme of nationality in the novel?', 'Tác giả khám phá chủ đề quốc tịch trong tiểu thuyết để làm nổi bật những căng thẳng và xung đột có thể xảy ra giữa các bản sắc văn hóa và quốc gia khác nhau.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100965, 'A', 'To highlight the importance of nationality in shaping our identity', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100965, 'B', 'To demonstrate the tensions and conflicts that can arise between different cultural and national identities', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100965, 'C', 'To provide a detailed description of the Irish landscape', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100965, 'D', 'To ignore the theme of nationality altogether', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100966, 101908, 'ROADMAP_QUIZ', 'What is the significance of the novel''s use of stream-of-consciousness narration in relation to the theme of identity?', 'Sử dụng thể loại kể chuyện dòng ý thức trong tiểu thuyết cho phép người đọc trải nghiệm thế giới thông qua mắt của một nhân vật duy nhất, làm nổi bật sự phức tạp của bản sắc.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100966, 'A', 'It allows the reader to experience the world through the eyes of a single character, highlighting the complexities of identity', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100966, 'B', 'It provides a detailed description of the physical appearance of the characters, reinforcing the idea that identity is fixed', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100966, 'C', 'It ignores the theme of identity altogether, focusing instead on other aspects of the novel', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100966, 'D', 'It offers a critical analysis of the characters'' actions and decisions, demonstrating the importance of identity in shaping our understanding of the world', false);
INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101909, 'reading-c1-a-sophisticated-marketing-strategy-report', 1019, 'A Sophisticated Marketing Strategy Report', 9, 'READING', 'C1', 1.0, 'A Sophisticated Marketing Strategy Report') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101909, 'The marketing team at XYZ Corporation has been tasked with developing a comprehensive marketing strategy to promote the company''s new product line. After conducting extensive market research, the team has identified several key demographics that are likely to be interested in the product. These demographics include individuals aged 25-45, with a high level of education and a medium to high income. The team has also identified several key marketing channels that will be used to reach these demographics, including social media, email marketing, and targeted online advertising. In addition, the team has developed a content marketing strategy that will include creating high-quality blog posts, videos, and infographics that will be shared on the company''s website and social media channels. The team has also established a public relations strategy that will include reaching out to key media outlets and influencers in the industry to generate buzz and excitement around the product. Finally, the team has developed a budget and timeline for the marketing campaign, which includes a total budget of $1 million and a timeline of 6 months. The team is confident that this comprehensive marketing strategy will be successful in promoting the company''s new product line and driving sales.', 'Vietnamese Translation:
