INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101910, 'reading-c1-quantum-computing-a-new-era-in-computing', 1019, 'Quantum Computing: A New Era in Computing', 10, 'READING', 'C1', 1.0, 'Quantum Computing: A New Era in Computing') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101910, 'Quantum computing is a new paradigm in computing that uses the principles of quantum mechanics to perform calculations. Unlike classical computers, which use bits to represent information, quantum computers use quantum bits or qubits. Qubits can exist in multiple states simultaneously, allowing for exponential scaling of computational power. This property makes quantum computers particularly well-suited for solving complex problems in fields such as chemistry and materials science.
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100972, 101910, 'ROADMAP_QUIZ', 'Máy tính lượng tử sử dụng các đơn vị tính toán nào?', 'Máy tính lượng tử sử dụng các qubits để thực hiện các phép tính.', 'C1') ON CONFLICT (id) DO NOTHING;
