INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100976, 101910, 'ROADMAP_QUIZ', 'Máy tính lượng tử có thể được sử dụng để giải quyết các vấn đề phức tạp trong các lĩnh vực nào?', 'Máy tính lượng tử có thể được sử dụng để giải quyết các vấn đề phức tạp trong các lĩnh vực như hóa học và khoa học vật liệu.', 'C1') ON CONFLICT (id) DO NOTHING;
