INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101912, 'reading-c1-the-dark-side-of-the-diamond-industry', 1019, 'The Dark Side of the Diamond Industry', 12, 'READING', 'C1', 1.0, 'The Dark Side of the Diamond Industry') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101912, 'The diamond industry has long been shrouded in mystery and controversy. Behind the sparkle of these precious stones lies a complex web of corruption, exploitation, and environmental degradation. In this investigative report, we will delve into the dark side of the diamond industry and expose the truth about the devastating impact it has on local communities and the environment.
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100982, 101912, 'ROADMAP_QUIZ', 'Ngành công nghiệp kim cương đã gây ra tác động tiêu cực như thế nào đối với các cộng đồng địa phương?', 'Ngành công nghiệp kim cương đã gây ra tác động tiêu cực đối với các cộng đồng địa phương bằng cách dẫn đến việc di dời và phá hủy môi trường.', 'C1') ON CONFLICT (id) DO NOTHING;
