INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100983, 101912, 'ROADMAP_QUIZ', 'Tại sao ngành công nghiệp kim cương cần phải được quản lý một cách có trách nhiệm?', 'Ngành công nghiệp kim cương cần phải được quản lý một cách có trách nhiệm để ưu tiên môi trường và cộng đồng địa phương.', 'C1') ON CONFLICT (id) DO NOTHING;
