INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101913, 'reading-c1-a-critique-of-sustainable-development-policies', 1019, 'A Critique of Sustainable Development Policies', 13, 'READING', 'C1', 1.0, 'A Critique of Sustainable Development Policies') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101913, 'The concept of sustainable development has been widely accepted as a guiding principle for economic growth and environmental protection. However, a closer examination of the policies implemented in the name of sustainable development reveals a more complex and nuanced reality. On one hand, these policies have led to significant reductions in greenhouse gas emissions and the preservation of natural habitats. On the other hand, they have also resulted in the displacement of local communities and the concentration of economic power in the hands of a few large corporations. Furthermore, the emphasis on economic growth has led to the exploitation of natural resources, undermining the very principles of sustainability. In order to truly achieve sustainable development, it is essential to rethink our current policies and prioritize the needs of local communities and the environment over economic interests. This requires a fundamental shift in our values and a willingness to challenge the status quo. Only then can we create a more equitable and sustainable future for all.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100986, 101913, 'ROADMAP_QUIZ', 'What is the main argument of the article?', 'Bài viết chỉ ra rằng các chính sách phát triển bền vững đã dẫn đến việc di dời cộng đồng địa phương và tập trung quyền lực kinh tế vào tay một số ít công ty lớn.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100986, 'A', 'Sustainable development policies are effective in reducing greenhouse gas emissions.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100986, 'B', 'Sustainable development policies have led to the displacement of local communities and the concentration of economic power.', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100986, 'C', 'Sustainable development policies prioritize the needs of local communities and the environment over economic interests.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100986, 'D', 'Sustainable development policies are not necessary for economic growth.', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100987, 101913, 'ROADMAP_QUIZ', 'What is the author''s opinion on the current policies of sustainable development?', 'Tác giả cho rằng các chính sách hiện tại cần phải được xem xét lại và ưu tiên nhu cầu của cộng đồng địa phương và môi trường hơn lợi ích kinh tế.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100987, 'A', 'The author supports the current policies and believes they are effective.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100987, 'B', 'The author is neutral and does not have an opinion on the current policies.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100987, 'C', 'The author believes the current policies are flawed and need to be rethought.', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100987, 'D', 'The author thinks the current policies are not necessary.', false);
