INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100989, 101913, 'ROADMAP_QUIZ', 'What is the author''s suggestion for achieving sustainable development?', 'Tác giả đề xuất rằng cần phải ưu tiên nhu cầu của cộng đồng địa phương và môi trường hơn lợi ích kinh tế để đạt được phát triển bền vững.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100989, 'A', 'Increase economic growth and reduce environmental protection.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100989, 'B', 'Prioritize the needs of local communities and the environment over economic interests.', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100989, 'C', 'Implement stricter regulations on businesses.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100989, 'D', 'Invest in renewable energy sources.', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100990, 101913, 'ROADMAP_QUIZ', 'What is the main challenge to achieving sustainable development?', 'Bài viết chỉ ra rằng ưu tiên lợi ích kinh tế hơn bảo vệ môi trường là một thách thức chính để đạt được phát triển bền vững.', 'C1') ON CONFLICT (id) DO NOTHING;
