INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100991, 'D', 'The economic benefits of renewable energy', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100992, 101914, 'ROADMAP_QUIZ', 'What are some of the solutions proposed by the authors to mitigate the effects of climate change on global food systems?', 'Các tác giả đề xuất một loạt các giải pháp để giảm thiểu tác động của biến đổi khí hậu đối với hệ thống thực phẩm toàn cầu, bao gồm việc áp dụng các phương pháp nông nghiệp có khả năng chống chịu với biến đổi khí hậu và phát triển các giống cây trồng có khả năng chống chịu với khí hậu.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100992, 'A', 'Adopting climate-resilient agricultural practices and developing climate-tolerant crop varieties', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (100992, 'B', 'Implementing policies to support small-scale farmers and promoting sustainable agriculture', false);
