INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101915, 'reading-c1-the-psychological-case-study-of-john-doe', 1019, 'The Psychological Case Study of John Doe', 15, 'READING', 'C1', 1.0, 'The Psychological Case Study of John Doe') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101915, 'John Doe, a 35-year-old marketing executive, had been experiencing symptoms of anxiety and depression for several months. He would often feel overwhelmed by his workload and struggled to sleep at night. Despite his best efforts, he found it difficult to concentrate and make decisions. His relationships with his family and friends began to suffer as a result of his increasing irritability and mood swings.
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (100996, 101915, 'ROADMAP_QUIZ', 'John Doe có tuổi tác bao nhiêu?', 'John Doe là một người quản lý marketing 35 tuổi.', 'C1') ON CONFLICT (id) DO NOTHING;
