INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101000, 101915, 'ROADMAP_QUIZ', 'Bản nghiên cứu của John Doe nhấn mạnh tầm quan trọng của việc gì?', 'Bản nghiên cứu của John Doe nhấn mạnh tầm quan trọng của việc tìm kiếm sự giúp đỡ chuyên nghiệp cho các vấn đề sức khỏe tâm thần và sự cần thiết của một phương pháp toàn diện để điều trị.', 'C1') ON CONFLICT (id) DO NOTHING;
