INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101918, 'reading-c1-the-impact-of-urbanization-on-social-relationships', 1019, 'The Impact of Urbanization on Social Relationships', 18, 'READING', 'C1', 1.0, 'The Impact of Urbanization on Social Relationships') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101918, 'Urbanization has been a dominant trend in the world for decades. As people move from rural areas to cities in search of better job opportunities and higher standards of living, their social relationships undergo significant changes. One of the most notable effects of urbanization is the decline of traditional social networks. In rural areas, people often rely on their family and community for support and companionship. However, in urban areas, people are more likely to form relationships based on shared interests and proximity. This shift can lead to a sense of loneliness and disconnection among urban dwellers. Furthermore, the fast-paced and competitive nature of city life can make it difficult for people to maintain meaningful relationships. According to a recent study, 60% of urban residents reported feeling isolated or disconnected from their community. To combat this issue, cities are implementing initiatives such as community gardens, public art projects, and social events to foster a sense of community and connection among residents. While urbanization has its drawbacks, it also presents opportunities for social innovation and connection.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101011, 101918, 'ROADMAP_QUIZ', 'What is the main effect of urbanization on social relationships?', 'Thành thị hóa đã dẫn đến sự suy giảm của các mạng lưới xã hội truyền thống.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101011, 'A', 'The decline of traditional social networks', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101011, 'B', 'The increase of social connections', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101011, 'C', 'The shift from family-based relationships to interest-based relationships', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101011, 'D', 'The improvement of community cohesion', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101012, 101918, 'ROADMAP_QUIZ', 'Why do people in urban areas form relationships based on shared interests and proximity?', 'Người dân trong các khu vực thành thị có xu hướng hình thành các mối quan hệ dựa trên các sở thích chung và khoảng cách.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101012, 'A', 'Because they have more time to socialize', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101012, 'B', 'Because they are more likely to meet people with similar interests', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101012, 'C', 'Because they are more likely to form relationships based on shared experiences', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101012, 'D', 'Because they are more likely to form relationships based on family ties', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101013, 101918, 'ROADMAP_QUIZ', 'What is the impact of the fast-paced and competitive nature of city life on social relationships?', 'Tính chất nhanh chóng và cạnh tranh của cuộc sống thành phố có thể khiến cho người dân khó duy trì các mối quan hệ có ý nghĩa.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101013, 'A', 'It makes it easier to maintain meaningful relationships', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101013, 'B', 'It has no impact on social relationships', false);
