INSERT INTO lessons (id, slug, module_id, title, order_index, lesson_type, level, difficulty_score, topic) VALUES (101920, 'reading-c1-a-manifesto-on-cultural-evolution', 1019, 'A Manifesto on Cultural Evolution', 20, 'READING', 'C1', 1.0, 'A Manifesto on Cultural Evolution') ON CONFLICT (id) DO NOTHING;
INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (101920, 'The concept of cultural evolution has been debated by scholars for centuries. Some argue that culture evolves through a process of gradual change, while others propose that it undergoes sudden and dramatic transformations. In this manifesto, we will explore the idea that cultural evolution is a complex and multifaceted process that cannot be reduced to a single theory or model. We will examine the role of technology, globalization, and social change in shaping our cultural landscape, and argue that a more nuanced understanding of cultural evolution is necessary to navigate the complexities of the modern world. As we move forward, we must recognize that cultural evolution is not a linear process, but rather a dynamic and adaptive system that is shaped by the interactions of individuals, groups, and societies. By embracing this complexity, we can work towards a more inclusive and equitable cultural future.', 'Vietnamese Translation:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101021, 101920, 'ROADMAP_QUIZ', 'What is the main idea of this manifesto?', 'Bản tuyên bố này khám phá ý tưởng rằng tiến hóa văn hóa là một quá trình phức tạp và đa dạng.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101021, 'A', 'Cultural evolution is a gradual process.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101021, 'B', 'Cultural evolution is a complex and multifaceted process.', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101021, 'C', 'Cultural evolution is a sudden and dramatic transformation.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101021, 'D', 'Cultural evolution is not a real concept.', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101022, 101920, 'ROADMAP_QUIZ', 'What role does technology play in shaping our cultural landscape?', 'Công nghệ đóng vai trò quan trọng trong việc hình thành cảnh quan văn hóa của chúng ta.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101022, 'A', 'Technology has no impact on our cultural landscape.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101022, 'B', 'Technology is a major driver of cultural change.', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101022, 'C', 'Technology is a minor factor in cultural evolution.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101022, 'D', 'Technology is not relevant to cultural evolution.', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101023, 101920, 'ROADMAP_QUIZ', 'What is the author''s argument about cultural evolution?', 'Tác giả lập luận rằng tiến hóa văn hóa là một hệ thống động và thích nghi.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101023, 'A', 'Cultural evolution is a linear process.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101023, 'B', 'Cultural evolution is a complex and adaptive system.', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101023, 'C', 'Cultural evolution is a sudden and dramatic transformation.', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101023, 'D', 'Cultural evolution is not a real concept.', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101024, 101920, 'ROADMAP_QUIZ', 'What is the purpose of this manifesto?', 'Bản tuyên bố này nhằm khám phá sự phức tạp của tiến hóa văn hóa.', 'C1') ON CONFLICT (id) DO NOTHING;
