INSERT INTO lesson_contents (lesson_id, body_text, media_url, duration_seconds) VALUES (102001, 'Transcript:
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101051, 102001, 'ROADMAP_QUIZ', 'What is a black hole?', 'Một lỗ đen là một vùng không gian có lực hấp dẫn mạnh đến mức không có gì, kể cả ánh sáng, có thể thoát ra.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101051, 'A', 'A region in space where the gravitational pull is weak', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101051, 'B', 'A region in space where the gravitational pull is so strong that nothing can escape', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101051, 'C', 'A type of star that is very large', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101051, 'D', 'A type of galaxy that is very small', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101052, 102001, 'ROADMAP_QUIZ', 'How are black holes formed?', 'Các lỗ đen được hình thành khi một ngôi sao lớn sụp đổ và lực hấp dẫn của nó làm cong không gian thời gian xung quanh.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101052, 'A', 'When a star is born', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101052, 'B', 'When a star collapses in on itself', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101052, 'C', 'When a galaxy is formed', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101052, 'D', 'When a planet is formed', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101053, 102001, 'ROADMAP_QUIZ', 'What is the event horizon?', 'Vùng không gian thời gian không thể thoát ra khỏi lỗ đen được gọi là vùng không thể quay trở lại.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101053, 'A', 'The point of no return', true);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101053, 'B', 'The point of return', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101053, 'C', 'The center of a black hole', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101053, 'D', 'The edge of a black hole', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101054, 102001, 'ROADMAP_QUIZ', 'What is a supermassive black hole?', 'Các lỗ đen siêu lớn có khối lượng hàng triệu hoặc hàng tỷ lần khối lượng của Mặt trời.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101054, 'A', 'A black hole that is very small', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101054, 'B', 'A black hole that is very large', true);
