INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101054, 'D', 'A type of galaxy that is very small', false);
INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101055, 102001, 'ROADMAP_QUIZ', 'Why is the study of black holes important?', 'Nghiên cứu về lỗ đen đã giúp chúng ta hiểu rõ hơn về vũ trụ và đã dẫn đến nhiều phát hiện quan trọng về lực hấp dẫn và hành vi của vật chất trong môi trường cực đoan.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101055, 'A', 'Because it helps us understand the universe', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101055, 'B', 'Because it helps us understand gravity', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101055, 'C', 'Because it helps us understand the behavior of matter in extreme environments', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101055, 'D', 'All of the above', true);
