INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101059, 102002, 'ROADMAP_QUIZ', 'Economist Lee có quan điểm gì về cách giải quyết các vấn đề kinh tế?', 'Economist Lee cho rằng cần tập trung vào việc cải thiện mức sống và tạo việc làm cho người dân.', 'C1') ON CONFLICT (id) DO NOTHING;
