INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101060, 102002, 'ROADMAP_QUIZ', 'Tại sao cuộc thảo luận này quan trọng?', 'Cuộc thảo luận này quan trọng bởi vì nó giúp giải quyết các vấn đề kinh tế và tạo cơ hội cho các chuyên gia thảo luận và chia sẻ ý kiến.', 'C1') ON CONFLICT (id) DO NOTHING;
