INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101061, 102003, 'ROADMAP_QUIZ', 'Chủ nghĩa hiện sinh nhấn mạnh sự gì?', 'Chủ nghĩa hiện sinh nhấn mạnh sự tự do và lựa chọn của cá nhân, cho phép con người tạo ra ý nghĩa của cuộc sống.', 'C1') ON CONFLICT (id) DO NOTHING;
