INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101064, 102003, 'ROADMAP_QUIZ', 'Chủ nghĩa hiện sinh có liên quan gì đến sự không chắc chắn?', 'Chủ nghĩa hiện sinh nhấn mạnh sự không chắc chắn, vì cuộc sống luôn chứa đựng sự không chắc chắn và không rõ ràng.', 'C1') ON CONFLICT (id) DO NOTHING;
