INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101065, 102003, 'ROADMAP_QUIZ', 'Chủ nghĩa hiện sinh có liên quan gì đến ý nghĩa của cuộc sống?', 'Chủ nghĩa hiện sinh nhấn mạnh ý nghĩa của cuộc sống, cho phép con người tạo ra ý nghĩa của cuộc sống.', 'C1') ON CONFLICT (id) DO NOTHING;
