INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101066, 102004, 'ROADMAP_QUIZ', 'Sự suy giảm trong tăng trưởng kinh tế hiện tại là do đâu?', 'Sự suy giảm trong tăng trưởng kinh tế hiện tại là do sự kết hợp của nhiều yếu tố, bao gồm sự giảm sút trong chi tiêu của người tiêu dùng và sự gia tăng trong các tranh chấp thương mại toàn cầu.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101066, 'A', 'Sự giảm sút trong chi tiêu của người tiêu dùng', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101066, 'B', 'Sự gia tăng trong các tranh chấp thương mại toàn cầu', true);
