INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101067, 102004, 'ROADMAP_QUIZ', 'Các nền kinh tế đang phát triển đang trải qua sự tăng trưởng kinh tế mạnh mẽ như thế nào?', 'Các nền kinh tế đang phát triển đang trải qua sự tăng trưởng kinh tế mạnh mẽ, nhưng sự tăng trưởng này chủ yếu được thúc đẩy bởi chi tiêu của chính phủ và đầu tư của chính phủ.', 'C1') ON CONFLICT (id) DO NOTHING;
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101067, 'A', 'Được thúc đẩy bởi chi tiêu của người tiêu dùng', false);
INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101067, 'B', 'Được thúc đẩy bởi đầu tư của doanh nghiệp', false);
