INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101068, 102004, 'ROADMAP_QUIZ', 'Giáo sư có quan điểm gì về tương lai của kinh tế toàn cầu?', 'Giáo sư có quan điểm lạc quan về tương lai của kinh tế toàn cầu, nhưng cũng cho rằng tương lai sẽ phụ thuộc vào nhiều yếu tố.', 'C1') ON CONFLICT (id) DO NOTHING;
