INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101069, 102004, 'ROADMAP_QUIZ', 'Giáo sư đề xuất giải pháp gì để đối phó với các thách thức kinh tế?', 'Giáo sư đề xuất sự hợp tác quốc tế là giải pháp để đối phó với các thách thức kinh tế.', 'C1') ON CONFLICT (id) DO NOTHING;
