INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101070, 102004, 'ROADMAP_QUIZ', 'Sự suy giảm trong tăng trưởng kinh tế có ảnh hưởng đến các nền kinh tế đang phát triển như thế nào?', 'Sự suy giảm trong tăng trưởng kinh tế sẽ làm giảm sự tăng trưởng kinh tế của các nền kinh tế đang phát triển.', 'C1') ON CONFLICT (id) DO NOTHING;
