INSERT INTO question_options (question_id, option_key, option_value, is_correct) VALUES (101070, 'B', 'Sự suy giảm trong tăng trưởng kinh tế sẽ không ảnh hưởng đến sự tăng trưởng kinh tế của các nền kinh tế đang phát triển', false);
