INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101072, 102005, 'ROADMAP_QUIZ', 'Tại sao Dr. Maria được trao giải Nobel?', 'Dr. Maria được trao giải Nobel vì công trình nghiên cứu về nguồn năng lượng sạch mới.', 'C1') ON CONFLICT (id) DO NOTHING;
