INSERT INTO questions (id, lesson_id, source_type, question_text, explanation, difficulty) VALUES (101141, 102019, 'ROADMAP_QUIZ', 'Theo lý thuyết cấu trúc, ý nghĩa của một từ hoặc cụm từ được xác định bởi mối quan hệ với các từ và cụm từ khác trong ngôn ngữ.', 'Theo lý thuyết cấu trúc, ý nghĩa của một từ hoặc cụm từ được xác định bởi mối quan hệ với các từ và cụm từ khác trong ngôn ngữ.', 'C1') ON CONFLICT (id) DO NOTHING;
