INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'pollute', 'Verb', '/ˈpɒlyuːt/', 'ô nhiễm', 'The factory is polluting the river.', 'Công ty đang ô nhiễm sông.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'recycle', 'Verb', '/rɪˈsaɪkəl/', 'hồi chế', 'We need to recycle more plastic.', 'Chúng ta cần phải hồi chế nhiều nhựa hơn.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'climate', 'Noun', '/ˈklaimət/', 'thời tiết', 'The climate in this region is very hot.', 'Thời tiết ở khu vực này rất nóng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'sustainable', 'Adjective', '/sʌstənəbəl/', 'sử dụng bền vững', 'We need to adopt sustainable practices in our daily life.', 'Chúng ta cần phải áp dụng các phương pháp sử dụng bền vững trong cuộc sống hàng ngày.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'biodiversity', 'Noun', '/baɪoʊdaɪˈvɛrsɪti/', 'sự đa dạng sinh học', 'The forest is home to a rich biodiversity.', 'Rừng là nơi có sự đa dạng sinh học phong phú.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'greenhouse', 'Noun', '/ˈɡriːnhaʊs/', 'nhà kính', 'The greenhouse is perfect for growing plants in the winter.', 'Nhà kính là nơi lý tưởng để trồng cây vào mùa đông.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'carbon', 'Noun', '/ˈkɑːrbən/', 'carbon', 'Carbon is an essential element for life.', 'Carbon là một nguyên tố quan trọng cho sự sống.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'emission', 'Noun', '/ɪˈmɪʃən/', 'xả thải', 'The factory''s emission is causing pollution.', 'Xả thải của nhà máy đang gây ô nhiễm.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'conservation', 'Noun', '/kənˌsɜːrvˈeɪʃən/', 'bảo tồn', 'We need to conserve water and energy.', 'Chúng ta cần phải bảo tồn nước và năng lượng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'fossil', 'Noun', '/ˈfɒsəl/', 'khoáng sản hóa thạch', 'The fossil is a remnant of a dinosaur.', 'Khoáng sản hóa thạch là một phần của khủng long.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'ocean', 'Noun', '/ˈoʊʃən/', 'biển', 'The ocean is home to many different species.', 'Biển là nơi có nhiều loài khác nhau.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'atmosphere', 'Noun', '/ətˈmɒsfɪər/', 'khí quyển', 'The atmosphere is essential for life.', 'Khí quyển là một phần quan trọng cho sự sống.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'ecosystem', 'Noun', '/iːˈkoʊsɪstəm/', 'môi trường sống', 'The forest is a delicate ecosystem.', 'Rừng là một hệ sinh thái nhạy cảm.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'pollen', 'Noun', '/ˈpɒlən/', 'phấn hoa', 'Pollen is a common allergen.', 'Phấn hoa là một loại dị ứng phổ biến.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'solar', 'Adjective', '/ˈsoʊlər/', 'năng lượng mặt trời', 'Solar panels are used to generate electricity.', 'Các tấm pin năng lượng mặt trời được sử dụng để tạo ra điện.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'recyclable', 'Adjective', '/rɪˈsaɪkəbəl/', 'hồi chế được', 'Plastic bottles are recyclable.', 'Bình nhựa là có thể hồi chế.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'depletion', 'Noun', '/dɪˈpliːʃən/', 'tình trạng cạn kiệt', 'The depletion of the ocean''s fish population is a concern.', 'Tình trạng cạn kiệt số lượng cá trong đại dương là một mối quan tâm.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'habitat', 'Noun', '/həˈbɪtæt/', 'môi trường sống', 'The habitat of the panda is in the mountains.', 'Môi trường sống của gấu trúc là ở núi.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'conservationist', 'Noun', '/kənˌsɜːrvˈeɪʃənɪst/', 'người bảo vệ môi trường', 'The conservationist is fighting to save the forest.', 'Người bảo vệ môi trường đang chiến đấu để cứu rừng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'lecturer', 'Noun', '/ˈlɛktʃərər/', 'giáo sư', 'The lecturer is very experienced.', 'Giáo sư này rất có kinh nghiệm.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'assignment', 'Noun', '/əsˈnaɪnmənt/', 'bài tập về nhà', 'The teacher gave us an assignment to finish by next week.', 'Giáo viên đã giao cho chúng tôi một bài tập về nhà để hoàn thành trong tuần tới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'examination', 'Noun', '/ˌeksəˈmeɪʃən/', 'khảo sát', 'The examination is next week.', 'Khảo sát sẽ diễn ra vào tuần tới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'research', 'Noun', '/rɪˈsɜːrtʃ/', 'nghiên cứu', 'The researcher spent years studying the effects of climate change.', 'Nghiên cứu viên đã dành nhiều năm để nghiên cứu tác động của biến đổi khí hậu.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'curriculum', 'Noun', '/kəˈrɪkjʊləm/', 'chương trình học', 'The new curriculum includes more emphasis on technology.', 'Chương trình học mới đã đặt trọng tâm nhiều hơn vào công nghệ.');
