INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'graduation', 'Noun', '/ˌɡrædʒʊˈeɪʃən/', 'tốt nghiệp', 'The graduation ceremony is next week.', 'Lễ tốt nghiệp diễn ra vào tuần tới.');
