INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'art', 'Noun', '/ɑrt/', 'tác phẩm nghệ thuật', 'She is a talented artist.', 'Cô ấy là một nghệ sĩ tài năng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'artist', 'Noun', '/ˈɑrtɪst/', 'người tạo tác nghệ thuật', 'He is a famous artist from Paris.', 'Anh ấy là một nghệ sĩ nổi tiếng từ Paris.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'audience', 'Noun', '/ˈɔːdɪəns/', 'khán giả', 'The audience was very quiet during the play.', 'Khán giả rất im lặng trong vở kịch.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'beauty', 'Noun', '/ˈbjuːtɪ/', 'đẹp', 'The beauty of nature is amazing.', 'Đẹp của thiên nhiên thật tuyệt vời.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'canvas', 'Noun', '/ˈkænvəs/', 'vải để vẽ tranh', 'She is painting on a large canvas.', 'Cô ấy đang vẽ tranh trên một tấm vải lớn.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'culture', 'Noun', '/ˈkʌltʃər/', 'văn hóa', 'The culture of Japan is very unique.', 'Văn hóa của Nhật Bản rất độc đáo.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'dance', 'Verb', '/dɑːns/', 'múa', 'She loves to dance in the evening.', 'Cô ấy yêu thích múa vào buổi tối.');
