INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'entertainment', 'Noun', '/ˌɛntərˈteɪnmənt/', 'giải trí', 'The movie is a great source of entertainment.', 'Phim là một nguồn giải trí tuyệt vời.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'festival', 'Noun', '/ˈfɛstɪvəl/', 'lễ hội', 'The music festival was very popular.', 'Lễ hội âm nhạc rất phổ biến.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'gallery', 'Noun', '/ˈɡæləri/', 'trường trưng bày nghệ thuật', 'The art gallery is open every day.', 'Trường trưng bày nghệ thuật mở cửa mỗi ngày.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'history', 'Noun', '/hɪˈstɔːri/', 'lịch sử', 'The history of art is very interesting.', 'Lịch sử nghệ thuật rất thú vị.');
