INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'museum', 'Noun', '/ˈmjuːzɪəm/', 'trường bảo tàng', 'The museum is open every day.', 'Trường bảo tàng mở cửa mỗi ngày.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'painting', 'Noun', '/ˈpeɪntɪŋ/', 'tranh vẽ', 'She is a talented painter.', 'Cô ấy là một nghệ sĩ vẽ tranh tài năng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'performance', 'Noun', '/ˌpərfərˈmæns/', 'hiệu suất', 'The performance of the play was excellent.', 'Hiệu suất của vở kịch rất xuất sắc.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'sculpture', 'Noun', '/ˈskʌltʃər/', 'tượng điêu', 'The sculpture is a great work of art.', 'Tượng điêu là một tác phẩm nghệ thuật tuyệt vời.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'theater', 'Noun', '/ˈθiːətər/', 'nhà hát', 'The theater is open every day.', 'Nhà hát mở cửa mỗi ngày.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'venture', 'Noun', '/ˈvɛntʃər/', 'sự mạo hiểm', 'She decided to take a venture into the tech industry.', 'Cô quyết định tham gia vào ngành công nghệ với sự mạo hiểm đó.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'launch', 'Verb', '/lɑːntʃ/', 'bắt đầu', 'The company will launch a new product next month.', 'Công ty sẽ bắt đầu sản phẩm mới vào tháng sau.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'market', 'Noun', '/ˈmɑːrkɪt/', 'thị trường', 'The company is trying to enter the market with a new product.', 'Công ty đang cố gắng tham gia thị trường với sản phẩm mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'network', 'Noun', '/ˈnɛtwərk/', 'mạng lưới', 'The company has a strong network of partners and suppliers.', 'Công ty có mạng lưới mạnh mẽ các đối tác và nhà cung cấp.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'partner', 'Noun', '/ˈpɑːtərnər/', 'đối tác', 'The company is looking for a partner to invest in the project.', 'Công ty đang tìm kiếm đối tác để đầu tư vào dự án.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'invest', 'Verb', '/ɪnˈvɛst/', 'đầu tư', 'The company is investing in a new factory.', 'Công ty đang đầu tư vào một nhà máy mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'strategy', 'Noun', '/ˈstrætɪdʒi/', 'chiến lược', 'The company has a clear strategy for expanding into new markets.', 'Công ty có chiến lược rõ ràng để mở rộng vào thị trường mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'target', 'Noun', '/ˈtɑːrgɪt/', 'mục tiêu', 'The company is setting a target to increase sales by 20%.', 'Công ty đang đặt mục tiêu tăng doanh số 20%.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'brand', 'Noun', '/brænd/', 'thương hiệu', 'The company is trying to build a strong brand in the market.', 'Công ty đang cố gắng xây dựng thương hiệu mạnh mẽ trên thị trường.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'funding', 'Noun', '/ˈfʌndɪŋ/', 'tài trợ', 'The company is seeking funding to launch a new product.', 'Công ty đang tìm kiếm tài trợ để bắt đầu sản phẩm mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'entrepreneur', 'Noun', '/ˌɒntrəˈprɒnə/', 'nhà kinh doanh', 'She is a successful entrepreneur with several businesses.', 'Cô là một nhà kinh doanh thành công với nhiều doanh nghiệp.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'innovate', 'Verb', '/ɪˈnɒveɪt/', 'tạo ra ý tưởng mới', 'The company is innovating in the field of renewable energy.', 'Công ty đang tạo ra ý tưởng mới trong lĩnh vực năng lượng tái tạo.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'marketplace', 'Noun', '/ˈmɑːrkɪtpleɪs/', 'thị trường', 'The company is trying to enter the marketplace with a new product.', 'Công ty đang cố gắng tham gia thị trường với sản phẩm mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'venture', 'Verb', '/ˈvɛntʃər/', 'mạo hiểm', 'She decided to venture into the tech industry.', 'Cô quyết định tham gia vào ngành công nghệ với sự mạo hiểm đó.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'launchpad', 'Noun', '/lɑːntʃpæd/', 'phát triển', 'The company is using a launchpad to develop a new product.', 'Công ty đang sử dụng một nền tảng phát triển để tạo ra sản phẩm mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'synergy', 'Noun', '/ˈsɪnədʒi/', 'sự tương tác', 'The company is looking for synergy between departments.', 'Công ty đang tìm kiếm sự tương tác giữa các bộ phận.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'disrupt', 'Verb', '/dɪsˈrʌpt/', 'phá vỡ', 'The company is trying to disrupt the traditional market with a new product.', 'Công ty đang cố gắng phá vỡ thị trường truyền thống với sản phẩm mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'ecosystem', 'Noun', '/ɪˈkoʊsɪstəm/', 'môi trường', 'The company is trying to create a sustainable ecosystem for its products.', 'Công ty đang cố gắng tạo ra một môi trường bền vững cho sản phẩm của mình.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'innovation', 'Noun', '/ɪˌnɒveɪʃən/', 'sự đổi mới', 'The company is focusing on innovation to stay competitive.', 'Công ty đang tập trung vào sự đổi mới để duy trì sự cạnh tranh.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'broadcast', 'Verb', '/ˈbrɒd.kɑːst/', 'phát sóng', 'The news will be broadcast on TV tonight.', 'Tin tức sẽ được phát sóng trên TV tonight.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'channel', 'Noun', '/ˈtʃæn.əl/', 'kênh', 'Please change the channel to watch the football match.', 'Xin chuyển kênh để xem trận đấu bóng đá.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'clip', 'Verb', '/klɪp/', 'chặt, cắt', 'Can you clip the news article for me?', 'Bạn có thể cắt bài báo tin tức cho tôi không?');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'comment', 'Noun', '/kəmˈent/', 'bình luận', 'I''d like to comment on the article.', 'Tôi muốn bình luận về bài viết.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'editor', 'Noun', '/ˈed.ɪtər/', 'chủ biên', 'The editor of the newspaper is very experienced.', 'Chủ biên của báo chí rất có kinh nghiệm.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'headline', 'Noun', '/ˈhæd.laɪn/', 'tiêu đề', 'The headline of the article is very catchy.', 'Tiêu đề của bài viết rất hấp dẫn.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'interview', 'Noun', '/ɪnˈtɜː.vjuː/', 'phỏng vấn', 'I''m going to interview the famous actor tomorrow.', 'Tôi sẽ phỏng vấn diễn viên nổi tiếng ngày mai.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'journalist', 'Noun', '/dʒɜːr.nəˈlɪst/', 'nhà báo', 'The journalist is very brave to report on the war.', 'Nhà báo rất dũng cảm để báo cáo về chiến tranh.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'magazine', 'Noun', '/mæɡəˈziːn/', 'tạp chí', 'I''m reading a magazine about fashion.', 'Tôi đang đọc tạp chí về thời trang.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'newspaper', 'Noun', '/njuːz.pɛpər/', 'báo chí', 'I''m reading the newspaper to stay up-to-date.', 'Tôi đang đọc báo chí để cập nhật thông tin.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'program', 'Noun', '/ˈproʊ.græm/', 'chương trình', 'The TV program is very entertaining.', 'Chương trình TV rất hấp dẫn.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'radio', 'Noun', '/ˈreɪ.ɪ.oʊ/', 'đài phát thanh', 'I''m listening to the radio while driving.', 'Tôi đang nghe đài phát thanh trong khi lái xe.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'reporter', 'Noun', '/rɪˈpɔːrtər/', 'nhà báo', 'The reporter is very brave to report on the war.', 'Nhà báo rất dũng cảm để báo cáo về chiến tranh.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'review', 'Verb', '/rɪˈvjuː/', 'đánh giá', 'I''m going to review the new movie tonight.', 'Tôi sẽ đánh giá bộ phim mới tonight.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'script', 'Noun', '/skrɪpt/', 'kịch bản', 'The script of the play is very well-written.', 'Kịch bản của vở kịch rất hay viết.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'series', 'Noun', '/ˈsɪər.iːz/', 'đoạn', 'The TV series is very popular.', 'Đoạn TV rất phổ biến.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'television', 'Noun', '/tɪ.vɪˈzɪʊ.ʃən/', 'tivi', 'I''m watching TV while eating dinner.', 'Tôi đang xem tivi trong khi ăn tối.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'transmit', 'Verb', '/trænzˈmɪt/', 'phát sóng', 'The radio station will transmit the news at 6pm.', 'Trạm phát thanh sẽ phát sóng tin tức lúc 6 giờ chiều.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'viewer', 'Noun', '/ˈvjuː.ər/', 'người xem', 'The viewer of the TV show is very loyal.', 'Người xem chương trình TV rất trung thành.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'family', 'Noun', '/ˈfæm.ɪli/', 'gia đình', 'She comes from a big family.', 'Cô ấy đến từ một gia đình lớn.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'friend', 'Noun', '/frend/', 'bạn', 'He''s a good friend of mine.', 'Anh ấy là một người bạn tốt của tôi.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'neighbor', 'Noun', '/ˈneɪbər/', 'người sống gần', 'Be careful not to disturb your neighbor.', 'Cẩn thận đừng làm phiền người sống gần bạn.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'community', 'Noun', '/kəˈmjuːn.ɪti/', 'xã hội', 'The community center is a great place to meet new people.', 'Trung tâm cộng đồng là một nơi tuyệt vời để gặp gỡ những người mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'culture', 'Noun', '/ˈkʌltʃər/', 'văn hóa', 'The culture of Japan is very different from ours.', 'Văn hóa của Nhật Bản rất khác biệt so với văn hóa của chúng ta.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'religion', 'Noun', '/rɪˈlɪdʒən/', 'tôn giáo', 'Many people in the world practice different religions.', 'Nhiều người trên thế giới thực hành các tôn giáo khác nhau.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'society', 'Noun', '/səˈsaɪ.əti/', 'xã hội', 'The society of our country is very developed.', 'Xã hội của đất nước chúng ta rất phát triển.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'tradition', 'Noun', '/trædɪˈtɪʃən/', 'truyền thống', 'We celebrate Christmas as a tradition.', 'Chúng tôi kỷ niệm Giáng sinh như một truyền thống.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'custom', 'Noun', '/ˈkʌstəm/', 'lịch sự', 'It''s a custom to remove your shoes before entering a temple.', 'Lịch sự là thói quen tháo giày trước khi vào đền thờ.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'etiquette', 'Noun', '/ɪˈtɪkɪt/', 'lễ nghi', 'She knew the etiquette of the royal court.', 'Cô ấy biết lễ nghi của triều đình.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'politeness', 'Noun', '/ˌpɒlɪˈtɪnəs/', 'lễ phép', 'He showed great politeness to his guests.', 'Anh ấy thể hiện sự lễ phép lớn lao với khách mời.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'kindness', 'Noun', '/ˈkaɪnd.nəs/', 'tình yêu thương', 'She showed kindness to the poor.', 'Cô ấy thể hiện tình yêu thương với người nghèo.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'help', 'Verb', '/hɛlp/', 'giúp đỡ', 'Can you help me with this task?', 'Bạn có thể giúp tôi với công việc này không?');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'support', 'Verb', '/səˈpɔːt/', 'ủng hộ', 'The government will support the economy.', 'Chính phủ sẽ ủng hộ nền kinh tế.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'respect', 'Noun', '/rɪˈspɛkt/', 'sự tôn trọng', 'We must respect our elders.', 'Chúng tôi phải tôn trọng người lớn tuổi.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'happiness', 'Noun', '/hæp.ɪnəs/', 'hạnh phúc', 'She felt happiness when she got the job.', 'Cô ấy cảm thấy hạnh phúc khi được nhận việc.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'friendship', 'Noun', '/ˈfrend.ʃɪp/', 'bạn bè', 'Their friendship lasted for many years.', 'Bề bạn bè của họ kéo dài trong nhiều năm.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'love', 'Noun', '/lʌv/', 'tình yêu', 'She felt love for her family.', 'Cô ấy cảm thấy tình yêu với gia đình.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'family', 'Noun', '/ˈfæm.ɪli/', 'gia đình', 'She comes from a big family.', 'Cô ấy đến từ một gia đình lớn.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'neighborhood', 'Noun', '/ˈneɪbərhʊd/', 'khu phố', 'The neighborhood is very quiet.', 'Khu phố rất yên tĩnh.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'ambition', 'Noun', '/æmˈbɪʃən/', 'mục tiêu', 'Her ambition is to become a doctor.', 'Mục tiêu của cô ấy là trở thành bác sĩ.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'analyze', 'Verb', '/ənˈælɪzaɪz/', 'xử lý, phân tích', 'We need to analyze the data before we can make a decision.', 'Chúng ta cần phân tích dữ liệu trước khi có thể đưa ra quyết định.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'assert', 'Verb', '/əˈsɜːrt/', 'tuyên bố', 'She asserted that she was not responsible for the mistake.', 'Cô tuyên bố rằng cô không phải là người gây ra lỗi đó.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'balance', 'Noun', '/ˈbæləns/', 'tính cân bằng', 'She had to balance her work and family life.', 'Cô phải cân bằng giữa công việc và cuộc sống gia đình.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'challenge', 'Noun', '/ˈtʃældʒ/', 'thách thức', 'The project was a challenge for the team.', 'Dự án đó là một thách thức đối với đội ngũ.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'commit', 'Verb', '/kəˈmɪt/', 'cam kết', 'She committed to helping her friend.', 'Cô cam kết sẽ giúp đỡ bạn của mình.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'confidence', 'Noun', '/kənˈfɪdəns/', 'tự tin', 'He gained confidence after completing the project.', 'Anh ấy có thêm tự tin sau khi hoàn thành dự án.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'decide', 'Verb', '/dɪˈsaɪd/', 'quyết định', 'We need to decide what to do next.', 'Chúng ta cần quyết định điều gì tiếp theo.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'develop', 'Verb', '/dɪˈvɛləp/', 'phát triển', 'The company is developing new products.', 'Công ty đang phát triển các sản phẩm mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'dream', 'Noun', '/driːm/', 'mộng ước', 'She had a dream about becoming a famous artist.', 'Cô có một giấc mơ về việc trở thành một nghệ sĩ nổi tiếng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'evaluate', 'Verb', '/ɪˈvæljuːeɪt/', 'đánh giá', 'We need to evaluate the performance of the team.', 'Chúng ta cần đánh giá hiệu suất của đội ngũ.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'focus', 'Noun', '/ˈfoʊkəs/', 'nhiệt độ', 'She had to focus on her studies.', 'Cô phải tập trung vào việc học tập.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'improve', 'Verb', '/ɪmˈproʊv/', 'tăng tiến', 'The company is trying to improve its services.', 'Công ty đang cố gắng cải thiện dịch vụ của mình.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'influence', 'Noun', '/ɪnˈflʊəns/', 'ảnh hưởng', 'She had a lot of influence on her friends.', 'Cô có ảnh hưởng lớn đối với bạn bè của mình.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'motivate', 'Verb', '/məˈtɪveɪt/', 'động viên', 'The coach motivated the team to win.', 'Hậu vệ động viên đội ngũ để giành chiến thắng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'opportunity', 'Noun', '/ˌɒpəˈtjuːnɪti/', 'cơ hội', 'She took advantage of the opportunity to travel.', 'Cô tận dụng cơ hội để đi du lịch.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'potential', 'Noun', '/pəˈtɛnʃəl/', 'sự tiềm ẩn', 'He has a lot of potential to become a great leader.', 'Anh ấy có tiềm năng lớn để trở thành một nhà lãnh đạo xuất sắc.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'realize', 'Verb', '/rɪˈaɪlaɪz/', 'nhận ra', 'She realized that she had made a mistake.', 'Cô nhận ra rằng cô đã mắc lỗi.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'self-confidence', 'Noun', '/sɛlfkənˈfɪdəns/', 'tự tin', 'He gained self-confidence after completing the project.', 'Anh ấy có thêm tự tin sau khi hoàn thành dự án.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'setback', 'Noun', '/ˈsɛt.bæk/', 'trở ngại', 'The project experienced a setback due to the lack of funding.', 'Dự án gặp trở ngại do thiếu nguồn tài trợ.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'strive', 'Verb', '/straɪv/', 'nỗ lực', 'She strives to be the best in her field.', 'Cô nỗ lực để trở thành người xuất sắc trong lĩnh vực của mình.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'experiment', 'Noun', '/ɛksˈpɛrɪmənt/', 'thử nghiệm', 'The scientists conducted an experiment to test the new theory.', 'Các nhà khoa học đã thực hiện một thử nghiệm để kiểm tra lý thuyết mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'innovation', 'Noun', '/ɪnəˈveɪʃən/', 'sự đổi mới', 'The company''s innovation in technology led to significant growth.', 'Sự đổi mới công nghệ của công ty đã dẫn đến sự tăng trưởng đáng kể.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'research', 'Noun', '/rɪˈsɜːrtʃ/', 'nghiên cứu', 'The team conducted research on the effects of climate change.', 'Đội đã thực hiện nghiên cứu về tác động của biến đổi khí hậu.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'hypothesis', 'Noun', '/hɪˈpɒθɪsɪs/', 'định đề', 'The scientist''s hypothesis was later proven to be incorrect.', 'Định đề của nhà khoa học sau đó đã được chứng minh là không đúng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'simulate', 'Verb', '/sɪmʊˈleɪt/', 'mô phỏng', 'The researchers simulated the effects of a natural disaster.', 'Các nhà nghiên cứu đã mô phỏng tác động của một thảm họa tự nhiên.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'analyze', 'Verb', '/ənˈælɪzaɪz/', 'phân tích', 'The data analyst spent hours analyzing the financial reports.', 'Nhân viên phân tích dữ liệu đã dành nhiều giờ để phân tích báo cáo tài chính.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'predict', 'Verb', '/prɪˈdɪkt/', 'đoán trước', 'The meteorologist predicted a storm would hit the city.', 'Nhà khí tượng học đã dự đoán một cơn bão sẽ đánh vào thành phố.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'evaluate', 'Verb', '/ɪˈvæliweɪt/', 'đánh giá', 'The teacher evaluated the student''s performance in the exam.', 'Giáo viên đã đánh giá kết quả học tập của học sinh trong kỳ thi.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'design', 'Noun', '/dɪˈzaɪn/', 'sáng tạo', 'The architect designed a new building for the city.', 'Kỹ sư kiến trúc đã thiết kế một tòa nhà mới cho thành phố.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'prototype', 'Noun', '/ˈproʊtətaɪp/', 'phiên bản thử nghiệm', 'The company created a prototype of the new smartphone.', 'Công ty đã tạo ra một phiên bản thử nghiệm của điện thoại mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'iteration', 'Noun', '/aɪˌtɛˈreɪʃən/', 'lần lặp lại', 'The software development team went through several iterations to perfect the code.', 'Đội phát triển phần mềm đã trải qua nhiều lần lặp lại để hoàn thiện mã nguồn.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'validate', 'Verb', '/vælɪˈdeɪt/', 'xác minh', 'The researcher validated the results of the study.', 'Nhà nghiên cứu đã xác minh kết quả nghiên cứu.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'iterate', 'Verb', '/aɪˈtɛreɪt/', 'lặp lại', 'The team iterated the design process to improve the product.', 'Đội đã lặp lại quá trình thiết kế để cải thiện sản phẩm.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'algorithm', 'Noun', '/ˌælɡəˈrɪðəm/', 'phương pháp giải quyết', 'The computer scientist developed an algorithm to optimize the code.', 'Kỹ sư máy tính đã phát triển một thuật toán để tối ưu hóa mã nguồn.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'simulate', 'Verb', '/sɪmʊˈleɪt/', 'mô phỏng', 'The researchers simulated the effects of a natural disaster.', 'Các nhà nghiên cứu đã mô phỏng tác động của một thảm họa tự nhiên.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'analyze', 'Verb', '/ənˈælɪzaɪz/', 'phân tích', 'The data analyst spent hours analyzing the financial reports.', 'Nhân viên phân tích dữ liệu đã dành nhiều giờ để phân tích báo cáo tài chính.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'predict', 'Verb', '/prɪˈdɪkt/', 'đoán trước', 'The meteorologist predicted a storm would hit the city.', 'Nhà khí tượng học đã dự đoán một cơn bão sẽ đánh vào thành phố.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'evaluate', 'Verb', '/ɪˈvæliweɪt/', 'đánh giá', 'The teacher evaluated the student''s performance in the exam.', 'Giáo viên đã đánh giá kết quả học tập của học sinh trong kỳ thi.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'design', 'Noun', '/dɪˈzaɪn/', 'sáng tạo', 'The architect designed a new building for the city.', 'Kỹ sư kiến trúc đã thiết kế một tòa nhà mới cho thành phố.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'bus', 'Noun', '/bʌs/', 'xe buýt', 'I take the bus to work every day.', 'Tôi đi xe buýt đến nơi làm việc mỗi ngày.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'station', 'Noun', '/ˈsteɪʃən/', 'bến xe', 'The train station is located in the city center.', 'Bến xe lửa nằm ở trung tâm thành phố.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'ticket', 'Noun', '/ˈtɪkɪt/', 'vé', 'Please buy a ticket before you board the bus.', 'Xin mua vé trước khi lên xe buýt.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'route', 'Noun', '/ruːt/', 'đường đi', 'The bus follows a specific route to the city center.', 'Xe buýt đi theo một đường đi cụ thể đến trung tâm thành phố.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'schedule', 'Noun', '/ˈskedʒʊl/', 'lịch trình', 'Please check the schedule for the bus departure time.', 'Xin kiểm tra lịch trình để biết giờ xuất phát của xe buýt.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'delay', 'Noun', '/dɪˈleɪ/', 'trễ hẹn', 'The flight was delayed due to bad weather.', 'Chuyến bay bị trễ hẹn do thời tiết xấu.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'transfer', 'Verb', '/trænsˈfɜːr/', 'chuyển tuyến', 'You need to transfer to a different bus to get to your destination.', 'Bạn cần chuyển tuyến sang một chiếc xe buýt khác để đến điểm đến.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'fare', 'Noun', '/fɛr/', 'giá vé', 'The fare for the taxi ride was very high.', 'Giá vé cho chuyến đi taxi rất cao.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'park', 'Verb', '/pɑːrk/', 'đỗ xe', 'Please park your car in the designated area.', 'Xin đỗ xe trong khu vực được chỉ định.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'traffic', 'Noun', '/ˈtræfɪk/', 'sự kẹt xe', 'There is heavy traffic on the highway.', 'Có sự kẹt xe nặng nề trên cao tốc.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'pedestrian', 'Noun', '/ˌpedɪˈstriːən/', 'người đi bộ', 'The pedestrian crossing is located at the intersection.', 'Đường đi bộ nằm ở giao lộ.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'sign', 'Noun', '/saɪn/', 'biển báo', 'The sign on the road indicates the direction to the city center.', 'Biển báo trên đường chỉ hướng đến trung tâm thành phố.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'route', 'Noun', '/ruːt/', 'đường đi', 'The bus follows a specific route to the city center.', 'Xe buýt đi theo một đường đi cụ thể đến trung tâm thành phố.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'schedule', 'Noun', '/ˈskedʒʊl/', 'lịch trình', 'Please check the schedule for the bus departure time.', 'Xin kiểm tra lịch trình để biết giờ xuất phát của xe buýt.');
