INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'transfer', 'Verb', '/trænsˈfɜːr/', 'chuyển tuyến', 'You need to transfer to a different bus to get to your destination.', 'Bạn cần chuyển tuyến sang một chiếc xe buýt khác để đến điểm đến.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'fare', 'Noun', '/fɛr/', 'giá vé', 'The fare for the taxi ride was very high.', 'Giá vé cho chuyến đi taxi rất cao.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'park', 'Verb', '/pɑːrk/', 'đỗ xe', 'Please park your car in the designated area.', 'Xin đỗ xe trong khu vực được chỉ định.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'traffic', 'Noun', '/ˈtræfɪk/', 'sự kẹt xe', 'There is heavy traffic on the highway.', 'Có sự kẹt xe nặng nề trên cao tốc.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'pedestrian', 'Noun', '/ˌpedɪˈstriːən/', 'người đi bộ', 'The pedestrian crossing is located at the intersection.', 'Đường đi bộ nằm ở giao lộ.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'sign', 'Noun', '/saɪn/', 'biển báo', 'The sign on the road indicates the direction to the city center.', 'Biển báo trên đường chỉ hướng đến trung tâm thành phố.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'arrive', 'Verb', '/əˈraɪv/', 'đến nơi', 'The train will arrive on time.', 'Tàu hỏa sẽ đến nơi đúng giờ.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'explore', 'Verb', '/ɛksˈploʊər/', 'khám phá', 'We decided to explore the new city.', 'Chúng tôi quyết định khám phá thành phố mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'tourist', 'Noun', '/ˈtʊərɪst/', 'du khách', 'The tourist information center is located near the train station.', 'Trung tâm thông tin du khách nằm gần ga tàu.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'attraction', 'Noun', '/əˈtrækʃən/', 'điểm thu hút', 'The Eiffel Tower is a major attraction in Paris.', 'Tháp Eiffel là một điểm thu hút chính ở Paris.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'itinerary', 'Noun', '/ˌɪtɪnˈɛri/', 'đường đi', 'Can you show me your itinerary for the trip?', 'Bạn có thể cho tôi xem lịch trình của chuyến đi không?');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'accommodation', 'Noun', '/əkəməˈdeɪʃən/', 'phòng nghỉ', 'We booked a hotel room for our accommodation.', 'Chúng tôi đã đặt phòng khách sạn cho chỗ ở.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'sightseeing', 'Noun', '/ˈsaɪtˌsiːɪŋ/', 'khám phá', 'We spent the day sightseeing in the city.', 'Chúng tôi đã dành cả ngày để khám phá thành phố.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'excursion', 'Noun', '/ɛksˈkɜːrʒən/', 'chuyến đi', 'We took an excursion to the nearby island.', 'Chúng tôi đã đi một chuyến đến đảo gần đó.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'passport', 'Noun', '/ˈpæs.pɔːrt/', 'hộ chiếu', 'Don''t forget to bring your passport when traveling abroad.', 'Hãy không quên mang hộ chiếu khi đi nước ngoài.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'visa', 'Noun', '/ˈviːsə/', 'giấy phép nhập cảnh', 'You need a visa to enter the United States.', 'Bạn cần giấy phép nhập cảnh để vào Mỹ.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'currency', 'Noun', '/ˈkɜːrɛnsi/', 'tiền tệ', 'The currency in Japan is the yen.', 'Tiền tệ ở Nhật Bản là yên.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'budget', 'Noun', '/ˈbʌdʒɪt/', 'kế hoạch tài chính', 'We need to make a budget for our trip.', 'Chúng tôi cần lập kế hoạch tài chính cho chuyến đi.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'transport', 'Verb', '/trænˈspɔːrt/', 'chuyển tải', 'We need to transport our luggage to the hotel.', 'Chúng tôi cần chuyển tải hành lý đến khách sạn.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'accommodate', 'Verb', '/əkəməˈdeɪt/', 'cung cấp chỗ ở', 'The hotel will accommodate us for the night.', 'Khách sạn sẽ cung cấp chỗ ở cho chúng tôi trong đêm.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'navigate', 'Verb', '/nævɪˈgeɪt/', 'đi đường', 'We need to navigate the city to get to the airport.', 'Chúng tôi cần đi đường thành phố để đến sân bay.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'orientation', 'Noun', '/ˌɔːriˈeɪʃən/', 'hướng dẫn', 'The hotel staff will give us an orientation about the city.', 'Nhân viên khách sạn sẽ hướng dẫn chúng tôi về thành phố.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'itinerary', 'Noun', '/ˌɪtɪnˈɛri/', 'đường đi', 'Can you show me your itinerary for the trip?', 'Bạn có thể cho tôi xem lịch trình của chuyến đi không?');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'exciting', 'Adjective', '/ɛksˈsaɪtɪŋ/', 'thú vị', 'The city has many exciting attractions.', 'Thành phố có nhiều điểm thu hút thú vị.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (100901, 'relax', 'Verb', '/rɪˈlæks/', 'thư giãn', 'We need to relax after the long trip.', 'Chúng tôi cần thư giãn sau chuyến đi dài.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'budget', 'Noun', '/ˈbʌdʒɪt/', 'kế hoạch tài chính', 'The company needs to create a budget for the new project.', 'Công ty cần tạo một kế hoạch tài chính cho dự án mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'capital', 'Noun', '/ˈkæpɪtəl/', 'tài sản ròng', 'The company''s capital is increasing every year.', 'Tài sản ròng của công ty đang tăng lên mỗi năm.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'credit', 'Noun', '/ˈkrɛdɪt/', 'sự tín nhiệm', 'She has good credit and can get a loan easily.', 'Cô có tín nhiệm tốt và có thể vay tiền dễ dàng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'debt', 'Noun', '/debt/', 'nợ', 'He has a lot of debt from his credit cards.', 'Anh ấy có nhiều nợ từ thẻ tín dụng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'economy', 'Noun', '/ɪˈkɒnəmi/', 'tình hình tài chính', 'The country''s economy is growing rapidly.', 'Tình hình tài chính của quốc gia đang phát triển nhanh chóng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'expense', 'Noun', '/ɪkˈspens/', 'chi phí', 'The company has a lot of expenses for marketing.', 'Công ty có nhiều chi phí cho quảng cáo.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'finance', 'Noun', '/ˈfaɪnəns/', 'tài chính', 'She works in finance and helps people with their investments.', 'Cô làm việc trong lĩnh vực tài chính và giúp người dân với các khoản đầu tư.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'income', 'Noun', '/ˈɪnkəm/', 'số tiền thu nhập', 'He has a high income from his job.', 'Anh ấy có thu nhập cao từ công việc.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'invest', 'Verb', '/ɪnˈvɛst/', 'đầu tư', 'She invested in a new startup company.', 'Cô đã đầu tư vào một công ty khởi nghiệp mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'investor', 'Noun', '/ɪnˈvɛstər/', 'người đầu tư', 'He is a successful investor and has made a lot of money.', 'Anh ấy là một nhà đầu tư thành công và đã kiếm được nhiều tiền.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'market', 'Noun', '/ˈmɑːrkɪt/', 'thị trường', 'The company is trying to enter the market with a new product.', 'Công ty đang cố gắng vào thị trường với một sản phẩm mới.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'profit', 'Noun', '/ˈprɒfɪt/', 'lợi nhuận', 'The company made a lot of profit last year.', 'Công ty đã kiếm được nhiều lợi nhuận trong năm ngoái.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'rate', 'Noun', '/reɪt/', 'tỷ lệ', 'The interest rate is very high right now.', 'Tỷ lệ lãi suất rất cao vào lúc này.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'save', 'Verb', '/seɪv/', 'lưu trữ', 'She tries to save money every month.', 'Cô cố gắng tiết kiệm tiền mỗi tháng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'spend', 'Verb', '/spend/', 'chi tiêu', 'He likes to spend his money on travel.', 'Anh ấy thích chi tiêu tiền vào du lịch.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'stock', 'Noun', '/stɒk/', 'cổ phiếu', 'She bought some stock in the company.', 'Cô đã mua cổ phiếu của công ty.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'tax', 'Noun', '/tæks/', 'thuế', 'He has to pay a lot of tax on his income.', 'Anh ấy phải trả một số tiền thuế lớn trên thu nhập của mình.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'trade', 'Noun', '/treɪd/', 'chuyển nhượng', 'The country is trying to increase its trade with other nations.', 'Quốc gia đang cố gắng tăng cường thương mại với các quốc gia khác.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'wealth', 'Noun', '/weɪlθ/', 'tài sản', 'He has a lot of wealth and can afford to travel anywhere.', 'Anh ấy có nhiều tài sản và có thể đi du lịch bất cứ nơi nào.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'strategic', 'Adjective', '/strætɪdʒɪk/', 'đúng chiến lược', 'The company''s strategic plan is to expand globally.', 'Kế hoạch chiến lược của công ty là mở rộng ra toàn cầu.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'synergy', 'Noun', '/ˈsɪnəɡri/', 'tác động cộng hưởng', 'The company is looking for synergy between departments.', 'Công ty đang tìm kiếm sự tương tác giữa các bộ phận để tạo ra hiệu quả cao hơn.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'diversify', 'Verb', '/dɪˈvɛrsɪfaɪ/', 'tái cơ cấu', 'The company is trying to diversify its product line.', 'Công ty đang cố gắng đa dạng hóa sản phẩm của mình.');
