INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'citizen', 'Noun', '/ˈsɪtɪzən/', 'người công dân', 'She is a proud citizen of this country.', 'Cô ấy tự hào là công dân của nước này.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'justice', 'Noun', '/ˈdʒʌstɪs/', 'tình trạng công bằng', 'The judge delivered a verdict of justice.', 'Hộ thẩm phán đưa ra phán quyết công bằng.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'punish', 'Verb', '/ˈpʌnɪʃ/', 'phạt tội', 'The court will punish the criminal.', 'Tòa án sẽ phạt tội phạm.');
