INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'punishment', 'Noun', '/ˈpʌnɪʃmənt/', 'phạt tội', 'The punishment was severe.', 'Phạt tội là nghiêm khắc.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'lawyer', 'Noun', '/ˈloʊjər/', 'luật sư', 'The lawyer argued the case.', 'Luật sư tranh luận vụ án.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'court', 'Noun', '/kɔːrt/', 'tòa án', 'The court will hear the case tomorrow.', 'Tòa án sẽ nghe vụ án ngày mai.');
INSERT INTO vocabulary_words (lesson_id, word, part_of_speech, phonetic, definition, example_sentence, example_translation) VALUES (101301, 'judge', 'Noun', '/dʒʌdʒ/', 'thẩm phán', 'The judge made a fair decision.', 'Thẩm phán đưa ra phán quyết công bằng.');
